NAME = 'ACV: A Conservative Version'
BOOK = 'I Chronicles'

CHAPTERS = {
    1: {
        1: 'Adam, Set, Enos,',
        2: 'Kenan, Mahalalel, Jared,',
        3: 'Enoh, Metuselah, Lameh,',
        4: 'Noe, Sem, Ham in Jafet.',
        5: 'Sinovi Jafetovi: Gomer, Magog, Madai, Javan, Tubal, Mesek in Tiras.',
        6: 'In sinovi Gomerjevi: Askenaz, Difat in Togarma.',
        7: 'In sinovi Javanovi: Elisa, Tarsis, Kitim in Rodanim.',
        8: 'Sinovi Hamovi: Kuš, Mizraim, Put in Kanaan.',
        9: 'Sinovi Kuševi pa: Seba, Havila, Sabta, Ragma in Sabteka. In sinova Ragmova: Šeba in Dedan.',
        10: 'In Kuš je rodil Nimroda; ta je začel mogočen biti na zemlji.',
        11: 'Mizraim pa je rodil Ludime, Anamime, Lehabime, Naftuhime,',
        12: 'Patrusime, Kasluhime (od katerih izvirajo Filistejci) in Kaftorime.',
        13: 'Kanaan pa je rodil Sidona, prvenca svojega, in Heta,',
        14: 'in Jebusejca, Amorejca, Girgasejca,',
        15: 'Hevejca, Arkejca, Sinejca,',
        16: 'Arvadejca, Zemarejca in Hamatejca.',
        17: 'Sinovi Semovi: Elam, Asur, Arpaksad, Lud, Aram, Uz, Hul, Geter in Mešek.',
        18: 'In Arpaksad je rodil Šelaha, Šelah pa Heberja.',
        19: 'Heberju pa sta se rodila dva sinova: ime enemu je bilo Peleg, ker se je v dneh njegovih razdelila zemlja, in bratu njegovemu je bilo ime Joktan.',
        20: 'In Joktan je rodil Almodada, Šelefa, Hazarmaveta, Jeraha,',
        21: 'Hadorama, Uzala, Dikla,',
        22: 'Ebala, Abimaela, Šeba,',
        23: 'Ofirja, Havila in Jobaba. Vsi ti so bili sinovi Joktanovi.',
        24: 'Sem, Arpaksad, Šelah,',
        25: 'Heber, Peleg, Regu,',
        26: 'Serug, Nahor, Terah,',
        27: 'Abram (to je Abraham).',
        28: 'Sinova Abrahamova: Izak in Izmael.',
        29: 'To so njiju rodovi: Prvenec Izmaelov Nebajot, potem Kedar, Adbeel, Mibsam,',
        30: 'Misma, Duma, Masa, Hadad in Tema,',
        31: 'Jetur, Nafiš in Kedema. Ti so sinovi Izmaelovi.',
        32: 'Sinovi Keture pa, priležnice Abrahamove: rodila je Zimrana, Joksana, Medana, Madiana, Išbaka in Šuaha. Sinova Joksanova: Šeba in Dedan.',
        33: 'In sinovi Madianovi: Efa, Efer, Hanok, Abida in Eldaa. Vsi ti so bili sinovi Keturini.',
        34: 'In Abraham je rodil Izaka. Sinova Izakova: Ezav in Izrael.',
        35: 'Sinovi Ezavovi: Elifaz, Reguel, Jeuš, Jalam in Korah.',
        36: 'Sinovi Elifazovi: Teman, Omar, Zefi, Gatam, Kenaz, Timna in Amalek.',
        37: 'Sinovi Reguelovi: Nahat, Zerah, Šama in Miza.',
        38: 'In sinovi Seirovi: Lotan, Šobal, Zibeon, Ana, Dišon, Ezer in Dišan.',
        39: 'In sinova Lotanova: Hori in Homam; in sestra Lotanova Timna.',
        40: 'Sinovi Šobalovi: Aljan, Manahat, Ebal, Šefi in Onam. In sinova Zibeonova: Aja in Ana.',
        41: 'Sin Anov: Dišon; in sinovi Dišonovi: Hamran, Ešban, Jitran in Keran.',
        42: 'Sinovi Ezerjevi: Bilhan, Zaavan, Jaakan. Sinova Dišonova: Uz in Aran.',
        43: 'To pa so kralji, ki so kraljevali v deželi Edomovi, preden je vladal kralj sinovom Izraelovim: Bela, sin Beorjev; in mesto njegovo se je imenovalo Dinhaba.',
        44: 'In ko je Bela umrl, je vladal Jobab, sin Zerahov iz Bozre, namesto njega.',
        45: 'In Jobab je umrl, in zakraljeval je namesto njega Hušam, iz dežele Temančanov.',
        46: 'In Hušam je umrl, in vladal je na mestu njegovem Hadad, sin Bedadov, ki je porazil Madiana na Moabski poljani. In njegovo mesto se je imenovalo Avit.',
        47: 'In ko je umrl Hadad, je zakraljeval na mestu njegovem Samla iz Masreke.',
        48: 'In Samla je umrl, in Savel iz Rehobota ob reki je kraljeval namesto njega.',
        49: 'In Savel je umrl, in Baal-hanan, sin Akborjev, je zakraljeval na mestu njegovem.',
        50: 'In Baal-hanan je umrl, in Hadad je vladal namesto njega; in njegovo mesto se je imenovalo Pagi, in ženi njegovi je bilo ime Mehetabela, hči Matrede, hčere Mezahabove.',
        51: 'In Hadad je umrl. In vojvode v Edomu so bili: vojvoda Timna, vojvoda Alja, vojvoda Jetet,',
        52: 'vojvoda Oholibama, vojvoda Ela, vojvoda Pinon,',
        53: 'vojvoda Kenaz, vojvoda Teman, vojvoda Mibzar,',
        54: 'vojvoda Magdiel, vojvoda Iram. Ti so vojvode v Edomu.',
    },
    2: {
        1: 'Ti so sinovi Izraelovi: Ruben, Simeon, Levi in Juda, Isahar in Zebulon,',
        2: 'Dan, Jožef in Benjamin, Neftali, Gad in Aser.',
        3: 'Sinovi Judovi: Ger, Onan in Šela, ti trije so se mu rodili iz hčere Šuvove, Kananejke. Ger pa, Judov prvenec, je bil hudoben v očeh Gospodovih, zato ga je usmrtil.',
        4: 'In Tamara, snaha in njegova, mu je rodila Pereza in Zeraha. Vseh sinov Judovih je bilo pet.',
        5: 'Sinova Perezova: Hezron in Hamul.',
        6: 'In sinovi Zerahovi: Zimri, Etan, Heman, Kalkol, Dara, vseh skupaj petero.',
        7: 'In sinovi Karmijevi: Ahar, ki je v nesrečo spravil Izraela, ko se je bil pregrešil pri prokletem.',
        8: 'In sin Etanov: Azarija.',
        9: 'In sinovi Hezronovi, ki so se mu rodili: Jerahmeel, Ram in Kelubaj.',
        10: 'In Ram je rodil Aminadaba, Aminadab pa je rodil Nahsona, vojvodo sinov Judovih;',
        11: 'in Nahson je rodil Salma, Salma pa je rodil Boaza,',
        12: 'in Boaz je rodil Obeda, Obed pa je rodil Jeseja,',
        13: 'a Jesej je rodil Eliaba, prvenca svojega, in Abinadaba, drugega, in Simea, tretjega,',
        14: 'Netanela, četrtega, Radaja, petega,',
        15: 'Ozema, šestega, Davida, sedmega;',
        16: 'njih sestri pa sta bili Zervija in Abigaila. In sinovi Zervijini: Abisaj in Joab in Asahel, trije.',
        17: 'In Abigaila je rodila Amasa; Amasov oče pa je bil Jeter Izmaelec.',
        18: 'Kaleb pa, sin Hezronov, je rodil otroke iz Azube, žene svoje, in iz Jeriote; in ti so bili sinovi njeni: Jeser, Sobab in Ardon.',
        19: 'In Azuba je umrla, in Kaleb si je vzel Efrato, ki mu je rodila Hura.',
        20: 'In Hur je rodil Urija, Uri pa je rodil Bezalela.',
        21: 'Pozneje je šel Hezron k hčeri Mahirja, očeta Gileadovega, ki jo je vzel za ženo, ko mu je bilo šestdeset let; in ona mu je rodila Seguba.',
        22: 'In Segub je rodil Jaira, ki je imel triindvajset mest v Gileadski pokrajini.',
        23: 'A Gesurci in Aramci so vzeli Jairove trge s Kenatom in njemu podložnimi mesti vred, šestdeset mest. Vsi ti so bili sinovi Mahirja, očeta Gileadovega.',
        24: 'In po smrti Hezronovi v Kaleb-efrati mu je rodila Abija, žena Hezronova, Ashurja, očeta Tekoa.',
        25: 'In sinovi Jerahmeela, prvenca Hezronovega, so bili: Ram, prvorojenec, in Buna, Oren, Ozem, Ahija.',
        26: 'In Jerahmeel je imel drugo ženo, ki ji je bilo ime Atara; ona je bila mati Onamova.',
        27: 'In sinovi Rama, prvenca Jerahmeelovega, so bili: Maaz, Jamin in Eker.',
        28: 'In sinova Onamova sta bila: Šamaj in Jada; in sinova Šamajeva: Nadab in Abisur.',
        29: 'In ženi Abisurjevi je bilo ime Abihaila in rodila mu je Ahbana in Molida.',
        30: 'In sinova Nadabova: Seled in Apaim; Seled pa je umrl brez otrok.',
        31: 'In sin Apaimov: Iši; in Išijev sin: Sesan; in sin Sesanov: Ahlaj.',
        32: 'Sinova pa Jada, brata Šamajevega: Jeter in Jonatan; Jeter pa je umrl brez otrok.',
        33: 'In sinova Jonatanova: Pelet in Zaza. Ti so bili sinovi Jerahmeelovi.',
        34: 'Sesan pa ni imel sinov, samo hčere. In Sesan je imel hlapca, Egipčana, ki mu je bilo ime Jarha.',
        35: 'In Sesan je dal svojo hčer Jarhu, hlapcu svojemu, za ženo; in ona mu je rodila Ataja.',
        36: 'In Ataj je rodil Natana, Natan pa je rodil Zabada;',
        37: 'in Zabad je rodil Eflala, in Eflal je rodil Obeda,',
        38: 'in Obed je rodil Jehuja, Jehu pa je rodil Azarija,',
        39: 'in Azarija je rodil Heleza, Helez pa je rodil Eleasa,',
        40: 'Eleasa pa je rodil Sismaja, Sismaj je pa rodil Saluma,',
        41: 'Salum pa je rodil Jekamija, Jekamija pa je rodil Elisama.',
        42: 'In sinovi Kaleba, brata Jerahmeelovega, so bili: Mesa, prvenec njegov, ki je bil oče Zifov, in sinovi Maresa, očeta Hebronovega.',
        43: 'In sinovi Hebronovi: Korah, Tapuah, Rekem in Sema.',
        44: 'In Sema je rodil Rahama, očeta Jorkeamovega, Rekem pa je rodil Šamaja.',
        45: 'In sin Šamajev je bil Maon, Maon pa je bil oče Betzurjev.',
        46: 'In Efa, Kalebova priležnica, je rodila Harana, Moza in Gazeza; Haran pa je rodil Gazeza.',
        47: 'In sinovi Jahdajevi: Regem, Jotam, Gesan, Pelet, Efa in Saaf.',
        48: 'Maaka, Kalebova priležnica, je rodila Seberja in Tirhana.',
        49: 'Rodila je tudi Saafa, očeta Madmana, Seva, očeta Mahbena, in očeta Gibejevega; hči Kalebova pa je bila Aksa.',
        50: 'Ti so bili sinovi Kalebovi: Sinovi Hura, prvenca Efrate: Šobal, oče Kirjat-jearima;',
        51: 'Salma, oče Betlehema, Haref, oče Betgaderja.',
        52: 'Šobal pa, oče Kirjat-jearima, je imel sinove: Haroe, Hazi, Menuhota.',
        53: 'In rodovine Kirjat-jearima: Jitrovci, Putovci, Sumatljani in Misrajci; iz njih so prišli Zoratovci in Estaolci.',
        54: 'Sinovi Salmajevi: Betlehem in Netofatejci, Atrot iz hiše Joabove, in polovica Manahatovcev, Zorovci.',
        55: 'In rodovine pisarjev, ki so prebivali v Jabezu: Tiratimci, Simeatimci, Sukatimci. Ti so Kenejci, ki so prišli iz Hamata, očeta hiše Rehabove.',
    },
    3: {
        1: 'Ti pa so sinovi Davidovi, ki so se mu rodili v Betlehemu: prvenec Amnon, iz Ahinoame Jezreelske; drugi Daniel, iz Abigaile Karmelske;',
        2: 'tretji Absalom, sin Maake, hčere Talmaja, kralja gesurskega; četrti Adonija, sin Hagite;',
        3: 'peti Sefatija, iz Abitale; šesti, Itream po Egli, ženi njegovi.',
        4: 'Šest se mu jih je rodilo v Hebronu; in tam je kraljeval sedem let in šest mesecev, v Jeruzalemu pa je kraljeval triintrideset let.',
        5: 'Ti pa so se mu rodili v Jeruzalemu: Simea, Sobab, Natan in Salomon, štirje, iz Batsuve, hčere Amieleve;',
        6: 'in Ibhar, Elisama, in Elifelet,',
        7: 'Noga, Nefeg, Jafija,',
        8: 'Elisama, Eliada in Elifelet, devet.',
        9: 'Vsi ti so bili sinovi Davidovi, razen sinov priležnic; Tamara pa je bila njih sestra.',
        10: 'Salomonov sin pa je bil Roboam, tega sin Abija, tega sin Asa, tega sin Josafat,',
        11: 'tega sin Joram, tega sin Ahazija, tega sin Joas,',
        12: 'tega sin Amazija, tega sin Azarija, tega sin Jotam,',
        13: 'tega sin Ahaz, tega sin Ezekija, tega sin Manasej,',
        14: 'tega sin Amon, tega sin Josija.',
        15: 'In sinovi Josijevi: prvenec Johanan, drugi Jojakim, tretji Zedekija, četrti Salum.',
        16: 'Sinova pa Jojakimova: tega sin Jekonija, tega sin Zedekija.',
        17: 'In sinovi Jekonija, jetnika: Sealtiel, sin njegov,',
        18: 'Malhiram, Pedaja, Senazar, Jekamija, Hosama in Nedabija.',
        19: 'In sinova Pedajeva: Zerubabel in Simej, in sinova Zerubabelova: Mesulam in Hananija, in Šelomita je bila njiju sestra;',
        20: 'in Hasuba, Ohel, Berekija, Hasadija, Jušab-hesed, pet.',
        21: 'In sinova Hananijeva: Pelatija in Jesaja; sinovi Refajevi, sinovi Arnanovi, sinovi Obadijevi, sinovi Sekanijevi.',
        22: 'In sinovi Sekanijevi: Semaja in sinovi Semajevi: Hatuš, Igal, Bariah, Nearija in Safat, šest.',
        23: 'In sinovi Nearijevi: Eljoenaj, Ezekija in Azrikam, trije.',
        24: 'In sinovi Eljoenajevi: Hodavija, Eliasib, Pelaja, Akub, Johanan, Delaja in Anani, sedem.',
    },
    4: {
        1: 'Sinovi Judovi: Perez, Hezron, Karmi, Hur in Šobal.',
        2: 'Reaja, sin Šobalov, pa je rodil Jahata, in Jahat je rodil Ahumaja in Lahada. To so rodovine Zoratovcev.',
        3: 'In ti so bili sinovi očeta Etama: Jezreel, Išma in Idbaš, in njih sestri je bilo ime Hazelelpona;',
        4: 'in Penuel, oče Gedorjev, in Ezer, oče Husajev. Ti so sinovi Hura, prvenca Efrate, očeta Betlehema.',
        5: 'Ashur pa, oče Tekoa, je imel dve ženi, Helo in Naaro.',
        6: 'In Naara mu je rodila Ahuzama, Heferja, Temenija, Ahastarija; ti so bili sinovi Naare.',
        7: 'Sinovi Hele pa so bili Zeret, Izhar in Etnan.',
        8: 'In Koz je rodil Anuba, Zobeba in rodovine Aharhela, sinú Harumovega.',
        9: 'In Jabez je bil imenitnejši mimo svojih bratov; in mati njegova mu je dala ime Jabez, rekoč: Ker sem ga rodila z bolečino.',
        10: 'In Jabez je klical Boga Izraelovega, govoreč: O da bi me obilo blagoslovil in razširil mejo mojo ter da bi bila roka tvoja z menoj in bi me branil zlega, da me ne zadene bolečina! In Bog je dal, da je prišlo, česar je prosil.',
        11: 'In Kelub, brat Suhajev, je rodil Mehirja, ki je bil oče Estona.',
        12: 'In Eston je rodil Betrafa, Paseaha in Tehina, očeta mesta Nahasa. To so možje iz Reke.',
        13: 'In sinova Kenazova: Otniel in Seraja; in sin Otnielov: Hatat.',
        14: 'In Meonotaj je rodil Ofra; in Seraja je rodil Joaba, očeta doline umetnikov; bili so namreč umetniki.',
        15: 'In sinovi Kaleba, sina Jefunovega: Iru, Ela in Naam; in sinovi Elovi in Kenaz.',
        16: 'In sinovi Jehalelelovi: Zif in Zifa,Tirja in Asarel.',
        17: 'In sinovi Ezrovi: Jeter, Mered, Efer in Jalon. In ona je rodila Mirjama, Šamaja in Isbaha, očeta Estemoa.',
        18: 'In žena njegova, Judinja, je rodila Jereda, očeta Gedorjevega, in Heberja, očeta Sokovega, in Jekutiela, očeta Zanoahovega. In ti so sinovi Bitije, hčere Faraonove, ki si jo je vzel Mered.',
        19: 'In sinova žene Hodijeve, sestre Nahamove: oče Keile, Garmejec, in Estemoa, Maakatovec.',
        20: 'Simonovi sinovi pa: Amnon, Rina, Benhanan in Tilon. In sinova Išejeva: Zohet in Benzohet.',
        21: 'Sinovi Šela, sinu Judovega: Ger, oče Lekov, in Laeda, oče Maresov, in rodovine hiše tistih, ki so tkali tenčico, iz hiše Asbea;',
        22: 'in Jokim in možje iz Kozebe, in Joas in Saraf, ki sta gospodovala Moabu in bivala v Lehemu. Ti zaznamki pa so stari.',
        23: 'Ti so bili lončarji in so stanovali po sadiščih in ograjah; prebivali so ondi pri kralju, da so delali zanj.',
        24: 'Sinovi Simeonovi: Nemuel in Jamin, Jarib, Zerah, Savel;',
        25: 'tega sin Salum, tega sin Mibsam, tega sin Misma.',
        26: 'In sinovi Mismovi: Hamuel, sin njegov, tega sin Zakur, tega sin Simej.',
        27: 'Simej pa je imel šestnajst sinov in šest hčer, ali bratje njegovi niso imeli veliko sinov, in vse njih rodovine se niso množile toliko, kolikor sinovi Judovi.',
        28: 'In prebivali so v Bersebi, Moladi, Hazar-suvalu,',
        29: 'v Bilhi, Ezemu, Toladu,',
        30: 'v Betuelu, Hormi, Ziklagu,',
        31: 'Bet-markabotu, Hazar-susimu in v Bet-bireju in v Saaraimu. Ta so bila njih mesta do kraljevanja Davidovega.',
        32: 'In njih vasi: Etam in Ajin, Rimon in Tohen in Asan, pet mest',
        33: 'in vse njih vasi, ki so bile okoli teh mest tja do Baala. To so bila njih prebivališča in so imeli svoj rodopis.',
        34: 'In Mesobab, Jamleh in Josa, sin Amazijev,',
        35: 'in Joel in Jehu, sin Josibijev, sinu Seraja, sinu Asiela,',
        36: 'in Eljoenaj, Jaakoba, Jesohaja, Asaja, Adiel, Jesimiel, Benaja',
        37: 'in Ziza, sin Sifijev, sinu Alona, sinu Jedaja, sinu Simrija, sinu Semaja:',
        38: 'ti po imenih omenjeni so bili knezi v svojih rodovinah; in njih očetovske hiše so se množile silno.',
        39: 'In šli so k vhodu v Gedor, proti vzhodu doline, da poiščejo pašnikov svoji drobnici.',
        40: 'In našli so obilnih in dobrih pašnikov, in kraj je bil prostran in miren in tih; kajti tisti, ki so ondi nekdaj prebivali, so bili Hamovega rodu.',
        41: 'In ti, zapisani po imenih, so prišli v dnevih Ezekija, kralja Judovega, in so razdejali njih šatore in Meunime, ki so bili ondi, in so jih s prokletjem zatrli, do tega dne, in se nastanili na njih mestu; kajti ondi je bila paša za njih drobnico.',
        42: 'In nekateri iz njih, iz sinov Simeonovih, petsto mož, so šli na Seirsko gorovje, in Pelatija in Nearija in Refaja in Uziel, sinovi Išijevi, so jim bili na čelu.',
        43: 'In pobili so ostanek Amalekovcev, ki so bili tja ušli, in nastanili so se ondi do tega dne.',
    },
    5: {
        1: 'In sinovi Rubena, prvenca Izraelovega (kajti on je bil prvorojenec, ali ker je onečastil očeta svojega posteljo, je bilo prvorojenstvo njegovo dano sinoma Jožefa, sinu Izraelovega; toda v rodopisu se to prvenstvo ne šteje.',
        2: 'Zakaj Juda je bil junak med svojimi brati in iz njega je prišel vojvoda; a pravica prvenstva je bila Jožefova),',
        3: 'sinovi Rubena, prvenca Izraelovega: Hanok, Palu, Hezron in Karmi.',
        4: 'Sinovi Joelovi: njegov sin Semaja, tega sin Gog, tega sin Simej,',
        5: 'tega sin Miha, tega sin Reaja, tega sin Baal,',
        6: 'tega sin Beera, ki ga je Tilgat-pilneser, kralj asirski, odvedel v ujetništvo; on je bil vojvoda Rubenovcem.',
        7: 'In njegovi bratje po svojih rodovinah, kakor so bili zapisani po svojem rodosledju: poglavar Jegiel in Zeharija',
        8: 'in Bela, sin Azaza, sinu Sema, sinu Joela, ki je prebival v Aroerju tja do Neba in Baalmeona;',
        9: 'in proti vzhodu je prebival tja do vhoda v puščavo od reke Evfrata; ker njih črede so se pomnožile v deželi Gileadski.',
        10: 'V dnevih Savlovih pa so se bojevali zoper Hagarence, ki so padli po njih roki; in nastanili so se v njih šatorih po vsej deželi vzhodno od Gileada.',
        11: 'In sinovi Gadovi so prebivali njim nasproti, v Basánski deželi tja do Saleka:',
        12: 'Joel, poglavar, in Safam, drugi, in Janaj in Safat v Basanu.',
        13: 'In njih bratje po svojih očetovskih hišah: Mihael, Mesulam, Seba, Joraj, Jakan, Zia in Heber, sedem.',
        14: 'Ti so bili sinovi Abihaila, sinu Hurija, sinu Jaroaha, sinu Gileada, sinu Mihaela, sinu Jesisaja, sinu Jahda, sinu Buza.',
        15: 'Ahi, sin Abdielov, sinu Gunija, je bil poglavar njih očetovske hiše.',
        16: 'In prebivali so v Gileadu v Basanu in po njega vaseh in po vseh Saronskih pašnikih tja do njih mej.',
        17: 'Vsi ti so bili zapisani v rodopise v dnevih Jotama, kralja Judovega, in v dnevih Jeroboama, kralja Izraelovega.',
        18: 'Sinov Rubenovih in Gadovih in polovice rodu Manasejevega, kar jih je bilo hrabrih mož, ki so nosili ščit in meč in streljali z lokom in so bili vešči vojni, je bilo štiriinštirideset tisoč sedemsto in šestdeset, ki so bili sposobni iti v boj.',
        19: 'In vojskovali so se s Hagarenci in z Jeturjem in Nafisom in Nodabom.',
        20: 'In Bog jim je pomagal zoper nje, in Hagarenci so jim bili dani v roko in vsi, ki so bili ž njimi; kajti klicali so k Bogu v boju, in dal se jim je izprositi, ker so zaupali vanj.',
        21: 'In odpeljali so si njih živino: petdeset tisoč njih velblodov, dvestoinpetdeset tisoč glav drobnice, dva tisoč oslov in sto tisoč ljudi.',
        22: 'Kajti padlo jih je mnogo ranjenih, ker je bil boj od Boga. In prebivali so na njih mestu do preselitve v ujetništvo.',
        23: 'In sinovi polovice rodu Manasejevega so prebivali v deželi: razmnožili so se od Basana do Baal-hermona in Senirja in do Hermonske gore.',
        24: 'In ti so bili poglavarji svojih očetovskih hiš: Efer, Iši, Eliel, Azriel, Jeremija, Hodavija in Jahdiel, vojni junaki, imenitni možje, glavarji svojih očetovskih hiš.',
        25: 'Ali izneverili so se Bogu očetov svojih in so nečistovali za bogovi narodov te dežele, ki jih je Bog iztrebil izpred njih obličja.',
        26: 'Tedaj je Bog obudil duha Pula, kralja asirskega, in duha Tilgat-pilneserja, kralja asirskega, in odpeljal jih je, namreč Rubence, Gadovce in polovico rodu Manasejevega, in jih je preselil v Halah in Habor in Haro in k reki Gozanu do tega dne.',
    },
    6: {
        1: 'Sinovi Levijevi: Gerson, Kahat in Merari.',
        2: 'In sinovi Kahatovi: Amram, Izhar, Hebron in Uziel.',
        3: 'In otroci Amramovi: Aron, Mojzes in Mirjama. In sinovi Aronovi: Nadab in Abihu, Eleazar in Itamar.',
        4: 'Eleazar je rodil Pinehasa, Pinehas je rodil Abisua;',
        5: 'Abisua pa je rodil Bukija, in Buki je rodil Uzija,',
        6: 'Uzi pa je rodil Zerahija, in Zerahija je rodil Merajota,',
        7: 'Merajot je rodil Amarija, in Amarija je rodil Ahituba;',
        8: 'Ahitub pa je rodil Zadoka, in Zadok je rodil Ahimaaza,',
        9: 'in Ahimaaz je rodil Azarija, Azarija pa je rodil Johanana,',
        10: 'in Johanan je rodil Azarija; ta je tisti, ki je izvrševal duhovniško službo v hiši, ki jo je Salomon sezidal v Jeruzalemu.',
        11: 'Azarija pa je rodil Amarija, in Amarija je rodil Ahituba,',
        12: 'in Ahitub je rodil Zadoka, in Zadok je rodil Saluma,',
        13: 'Salum pa je rodil Hilkija, in Hilkija je rodil Azarija,',
        14: 'Azarija pa je rodil Seraja, in Seraja je rodil Jehozadaka,',
        15: 'in Jehozadak je šel v ujetništvo, ko je Gospod preselil Judo in Jeruzalem po roki Nebukadnezarja.',
        16: 'Sinovi Levijevi: Gersom, Kahat in Merari.',
        17: 'In ti sta imeni sinov Gersomovih: Libni in Simej.',
        18: 'Sinovi Kahatovi pa so bili Amram, Izhar, Hebron in Uziel.',
        19: 'Sinova Merarijeva: Mahli in Musi. To so rodovine levitov po njih očetovskih hišah.',
        20: 'Od Gersoma: tega sin Libni, tega sin Jahat, tega sin Zima,',
        21: 'tega sin Joah, tega sin Ido, tega sin Zerah, tega sin Jeatraj.',
        22: 'Sinovi Kahatovi: njegov sin Aminadab, tega sin Korah, tega sin Asir,',
        23: 'tega sin Elkana, tega sin Ebiasaf, tega sin Asir,',
        24: 'tega sin Tahat, tega sin Uriel, tega sin Uzija, tega sin Savel.',
        25: 'In sinovi Elkana: Amasaj in Ahimot,',
        26: 'sinovi Elkanovi: tega sin Zofaj, in tega sin Nahat,',
        27: 'tega sin Eliab, tega sin Jehoram, tega sin Elkana.',
        28: 'In sinova Samuelova: prvenec Vašni-Joel, drugi Abija.',
        29: 'Sinovi Merarijevi: Mahli, tega sin Libni, tega sin Simej, tega sin Uza,',
        30: 'tega sin Simea, tega sin Hagija, tega sin Asaja.',
        31: 'Ti pa so, ki jih je David postavil v vodstvo za petje v hiši Gospodovi, potem ko je skrinja dobila mesto počivanja.',
        32: 'In služili so s petjem pred prebivališčem shodnega šatora, dokler ni sezidal Salomon hiše Gospodove v Jeruzalemu, in so stali v službi svoji po svojem redu.',
        33: 'In ti so, ki so stali v službi, in njih sinovi: od sinov Kahatovcev: Heman, pevec, sin Joela, sinu Samuela,',
        34: 'sinu Elkana, sinu Jerohama, sinu Eliela, sinu Toaha,',
        35: 'sinu Zufa, sinu Elkana, sinu Mahata, sinu Amasaja,',
        36: 'sinu Elkana, sinu Joela, sinu Azarija, sinu Zefanija,',
        37: 'sinu Tahata, sinu Asirja, sinu Ebiasafa, sinu Koraha,',
        38: 'sinu Izharja, sinu Kahata, sinu Levija, sinu Izraelovega.',
        39: 'In brat njegov je bil Asaf, ki je stal na njegovi desnici, namreč Asaf, sin Berekija, sinu Simea,',
        40: 'sina Mihaela, sinu Baaseja, sinu Malkija,',
        41: 'sinu Etnija, sinu Zeraha, sinu Adaja,',
        42: 'sinu Etana, sinu Zima, sinu Simeja,',
        43: 'sinu Jahata, sinu Gersoma, sinu Levijevega.',
        44: 'Na levici so stali njih bratje, sinovi Merarijevi: Etan, sin Kisija, sinu Abdija, sinu Maluka,',
        45: 'sinu Hasabija, sinu Amazija, sinu Hilkija,',
        46: 'sinu Amzija, sinu Banija, sinu Semerja,',
        47: 'sinu Mahlija, sinu Musija, sinu Merarija, sinu Levijevega.',
        48: 'In njih bratje, leviti, so bili določeni za vso službo pri prebivališču hiše Božje.',
        49: 'Aron in sinovi njegovi pa so darovali na žgalnem oltarju in na kadilnem oltarju in so bili za vso službo Najsvetejšega ter da opravljajo spravo za Izraela, po vsem, kar je bil Mojzes, hlapec Božji, zapovedal.',
        50: 'In ti so sinovi Aronovi: Eleazar, sin njegov, tega sin Pinehas, tega sin Abisua,',
        51: 'tega sin Buki, tega sin Uzi, tega sin Zerahija,',
        52: 'tega sin Merajot, tega sin Amarija, tega sin Ahitub,',
        53: 'tega sin Zadok, tega sin Ahimaaz.',
        54: 'To pa so njih bivališča, po njih seliščih v njih mejah: Sinovom Aronovim iz rodu Kahatovcev (njim je bil namreč prvi delež)',
        55: 'so dali Hebron v deželi Judovi in njegove pašnike okoli;',
        56: 'a njive mesta in njegove vasi so dali Kalebu, sinu Jefunovemu.',
        57: 'In sinovom Aronovim so dali zavetna mesta: Hebron, Libno s pašniki, Jatir in Estemoo s pašniki,',
        58: 'Holon s pašniki, Debir s pašniki,',
        59: 'Asan s pašniki, Betsemes s pašniki.',
        60: 'In od rodu Benjaminovega: Gebo in njene pašnike, Alemet s pašniki in Anatot s pašniki. Vseh njih mest po njih rodovinah je bilo trinajst mest.',
        61: 'Drugim sinom Kahatovim so po žrebu dali od rodovin rodu... od polovice rodu, polovice Manaseja, deset mest.',
        62: 'In sinovom Gersomovim, po njih rodovinah, od rodu Isaharjevega in od rodu Aserjevega in od rodu Neftalijevega in od rodu Manasejevega v Basánu: trinajst mest.',
        63: 'Sinovom Merarijevim so dali po žrebu, po njih rodovinah, od rodu Rubenovega in od rodu Gadovega in od rodu Zebulonovega: dvanajst mest.',
        64: 'Dali so torej sinovi Izraelovi levitom mesta ž njih pašniki.',
        65: 'In so dali po žrebu od rodu sinov Judovih in od rodu sinov Simeonovih in od rodu sinov Benjaminovih ta mesta, ki so jih imenovali po imenu.',
        66: 'In nekatere rodovine sinov Kahatovih so dobile mesta v svojo oblast od rodu Efraimovega.',
        67: 'In dali so jim zavetna mesta: Sihem v Efraimskem gorovju in njegove pašnike, tudi Gezer s pašniki,',
        68: 'Jokmean s pašniki, Bethoron s pašniki,',
        69: 'Ajalon s pašniki, Gat-rimon s pašniki;',
        70: 'in od polovice rodu Manasejevega: Aner s pašniki, Bileam s pašniki. Ta so dali rodovinam ostalih sinov Kahatovih.',
        71: 'Sinovom Gersomovim so dali: od polovice rodu Manasejevega: Golan v Basánu in njegove pašnike, Astarot s pašniki,',
        72: 'in od rodu Isaharjevega: Kedes s pašniki, Daberat s pašniki,',
        73: 'Ramot s pašniki, Anem s pašniki;',
        74: 'in od rodu Aserjevega: Masal in njegove pašnike, Abdon s pašniki,',
        75: 'Hukok s pašniki, Rehob s pašniki;',
        76: 'in od rodu Neftalijevega: Kedes v Galileji in njegove pašnike, Hamon s pašniki in Kirjataim s pašniki.',
        77: 'Drugim sinovom Merarijevim: od rodu Zebulonovega: Rimono s pašniki, Tabor s pašniki;',
        78: 'in za Jordanom pri Jerihu, na vzhodni strani Jordana, so jim dali od rodu Rubenovega: Bezer v puščavi in njegove pašnike, Jahzo s pašniki,',
        79: 'Kedemot s pašniki, Mefaat s pašniki;',
        80: 'in od rodu Gadovega: Ramot v Gileadu in njegove pašnike, Mahanaim s pašniki,',
        81: 'Hesbon s pašniki in Jazer s pašniki.',
    },
    7: {
        1: 'In sinovi Isaharjevi so bili: Tola in Puva, Jasub in Simron, štirje.',
        2: 'In sinovi Tolovi: Uzi, Refaja, Jeriel, Jahmaj, Ibsam in Samuel, poglavarji očetovskih hiš svojih, Tolovih, hrabri junaki po svojih rodovinah; njih število v dnevih Davidovih je bilo dvaindvajset tisoč in šeststo.',
        3: 'In sinovi Uzijevi: Izrahija, in sinovi Izrahijevi: Mihael, Obadija, Joel, Išija, pet, vsi poglavarji.',
        4: 'In pri njih so bile, po njih rodovih, po njih očetovskih hišah, vojne čete, šestintrideset tisoč mož; kajti imeli so mnogo žen in sinov.',
        5: 'In njih bratov, po vseh rodovinah Isaharjevih, hrabrih junakov, vseh zapisanih v rodopisu, je bilo sedeminosemdeset tisoč.',
        6: 'Benjaminovi sinovi: Bela, Beker in Jediael, trije.',
        7: 'In sinovi Belovi: Ezbon, Uzi, Uziel, Jerimot in Iri, pet, poglavarji v hišah svojih očetov, hrabri možje; in bilo jih je v rodopisu zapisanih dvaindvajset tisoč in štiriintrideset.',
        8: 'In sinovi Bekerjevi: Zemira, Joas, Eliezer, Eljoenaj, Omri, Jeremot, Abija, Anatot in Alemet. Vsi ti so bili sinovi Bekerjevi.',
        9: 'In vpisanih je bilo v rodopisu, po svojih rodovih, poglavarji hiš svojih očetov, hrabrih mož, dvajset tisoč in dvesto.',
        10: 'In sinovi Jediaelovi: Bilhan, in Bilhanovi sinovi: Jeuš, Benjamin, Ehud, Kenaana, Zetan, Tarsis in Ahisahar.',
        11: 'Vsi ti so bili sinovi Jediaelovi, po svojih zarodnikih, hrabri junaki, sedemnajst tisoč in dvesto, ki so bili sposobni iti z vojsko v boj.',
        12: 'Tudi Supimi in Hupimi, sinovi Irijevi. Husimi, sinovi Aherjevi.',
        13: 'Sinovi Neftalijevi: Jahziel, Guni, Jezer in Salum, sinovi Bilhe.',
        14: 'Sinovi Manasejevi: Asriel, ki ga je rodila...; njegova aramejska priležnica je rodila Mahirja, očeta Gileadovega.',
        15: 'Mahir pa si je vzel ženo od Hupimov in Supimov, in ime sestri njeni je bilo Maaka. In ime drugemu sinu je bilo Zelofad; Zelofad pa je imel hčere.',
        16: 'In Maaka, žena Mahirjeva, je rodila sina in ga je imenovala Peresa; in bratu njegovemu je bilo ime Seres, in sinova njegova sta bila Ulam in Rekem.',
        17: 'In sin Ulamov: Bedan. Ti so bili sinovi Gileada, sina Mahirja, sinu Manasejevega.',
        18: 'In sestra njegova Moleketa je rodila Ishoda in Abiezerja in Mahla.',
        19: 'In sinovi Semidovi so bili: Ahian, Sihem, Likhi in Aniam.',
        20: 'In sinovi Efraimovi: Sutelah, in Bered, sin njegov, in tega sin Tahat, tega sin Elada, tega sin Tahat,',
        21: 'tega sin Zabad in tega sin Sutelah, in Ezer in Elad. In umorili so jih možje iz Gata, rojeni v deželi, ker so prišli doli, da se polaste njih živine.',
        22: 'In njih oče Efraim je žaloval veliko dni, in bratje njegovi so ga prišli tolažit.',
        23: 'In šel je k svoji ženi, in je spočela in rodila sina; in imenoval je ime njegovo Berija, ker je bila hiša njegova v nesreči.',
        24: 'In hči njegova je bila Seera, ki je postavila Dolenji in Zgornji, Bethoron in Uzen-seero.',
        25: 'In Refah je bil sin njegov in Resef, in tega sin Telah, in tega sin Tahan,',
        26: 'tega sin Ladan, tega sin Amihud, tega sin Elisama,',
        27: 'tega sin Nun, tega sin Jozue.',
        28: 'In njih posestva in bivališča so bila: Betel in njemu podložne vasi, proti vzhodu pa Naaran in proti zahodu Gezer in njegove podložne vasi, tudi Sihem in njemu podložne vasi tja do Aze in njenih podložnih vasi;',
        29: 'in poleg meje sinov Manasejevih: Betsean in njegove podložne vasi, Taanah in njemu podložne vasi, Megido in njemu podložne vasi, Dor in njemu podložne vasi. V teh so prebivali sinovi Jožefa, sina Izraelovega.',
        30: 'Sinovi Aserjevi: Jimna, Jišva, Jišvi, Berija in Seraha, njih sestra.',
        31: 'In sinova Berijeva: Heber in Malkiel, ki je bil oče Birzavita.',
        32: 'In Heber je rodil Jafleta in Somerja in Hotama in Suvo, njih sestro.',
        33: 'In sinovi Jafletovi: Pasak, Bimhal in Asvat. To so otroci Jafletovi.',
        34: 'In sinovi Somerjevi: Ahi, Rohga, Huba in Aram.',
        35: 'In. sinovi Helema, brata njegovega: Zofah, Imna, Seles in Amal.',
        36: 'Sinovi Zofahovi: Suah, Harnefer, Sual, Beri, Imra,',
        37: 'Bezer, Hod, Sama, Silsa, Jitran in Beera.',
        38: 'In sinovi Jeterjevi: Jefune, Pispa in Ara.',
        39: 'In sinovi Ulovi: Arah, Haniel in Rizja.',
        40: 'Vsi ti so bili sinovi Aserjevi, poglavarji očetovskih hiš, izbrani in junaški možje, prvaki knezov. In število njih vpisanih v rodopise za službo pri vojski je bilo šestindvajset tisoč mož.',
    },
    8: {
        1: 'Benjamin pa je rodil Bela, prvenca svojega, Ašbela, drugega, in Aheraha, tretjega,',
        2: 'Noha, četrtega, in Rafa, petega.',
        3: 'In Bela je imel sinove: Adarja, Gera in Abihuda,',
        4: 'Abisua, Naamana in Ahoaha,',
        5: 'Gera, Sefufana in Hurama.',
        6: 'In ti so sinovi Ehudovi, ti so bili poglavarji očetovskih hiš prebivalcem v Gebi, in odpeljali so jih ujete v Manahat,',
        7: 'namreč Naaman, Ahija in Gera, ta jih je odpeljal; in rodil je Uza in Ahihuda.',
        8: 'Saharaim je rodil otroke v Moabski deželi, potem ko je bil odslovil Husimo in Baaro, ženi svoji.',
        9: 'In rodil je s Hodeso, ženo svojo: Jobaba, Zibija, Mesa, Malkama,',
        10: 'Jeuza, Sakija in Mirma. Ti so bili sinovi njegovi, poglavarji očetovskih hiš.',
        11: 'S Husimo pa je rodil Abituba in Elpaala.',
        12: 'In sinovi Elpaalovi: Heber, Misam in Semed, ki je sezidal Ono in Lod in njemu podložne vasi,',
        13: 'in Berija in Sema, ki sta bila poglavarja očetovskih hiš prebivalcem v Ajalonu, ki sta zapodila v beg prebivalce iz Gata;',
        14: 'in Ahio, Sasak in Jeremot,',
        15: 'Zebadija, Arad in Eder,',
        16: 'Mihael, Ispa in Joha, sinovi Berijevi;',
        17: 'in Zebadija, Mesulam, Hizki, Heber,',
        18: 'Ismeraj, Izlija in Jobab, sinovi Elpaalovi. –',
        19: 'In Jakim, Zihri, Zabdi,',
        20: 'Elienaj, Ziletaj, Eliel,',
        21: 'Adaja, Beraja in Simrat, sinovi Simejevi.',
        22: 'Ispan, Heber, Eliel,',
        23: 'Abdon, Zihri, Hanan,',
        24: 'Hananija, Elam, Antotija,',
        25: 'Ifdeja in Penuel, sinovi Sasakovi.',
        26: 'In Samseraj, Seharija, Atalija,',
        27: 'Jaaresija, Elija in Zihri, sinovi Jerohamovi.',
        28: 'Ti so bili poglavarji očetovskih hiš po svojih rodovinah, prvaki; ti so prebivali v Jeruzalemu.',
        29: 'In v Gibeonu je prebival oče Gibeonov, čigar ženi je bilo ime Maaka.',
        30: 'In prvorojeni sin njegov je bil Abdon, potem Zur, Kis, Baal, Nadab,',
        31: 'Gedor, Ahio in Zeher.',
        32: 'In Miklot je rodil Simea. Ti so tudi prebivali z brati svojimi v Jeruzalemu, bratom svojim nasproti.',
        33: 'In Ner je rodil Kisa, Kis pa je rodil Savla, Savel pa je rodil Jonatana in Malhisua in Abinadaba in Esbaala.',
        34: 'In sin Jonatanov je bil Merib-baal, in Merib-baal je rodil Miha.',
        35: 'In sinovi Mihovi: Piton, Melek, Tarea in Ahaz.',
        36: 'In Ahaz je rodil Jehoada, in Jehoada je rodil Alemeta in Azmaveta in Zimrija; Zimri pa je rodil Moza;',
        37: 'Moza pa je rodil Binea; in njegov sin je bil Rafa, tega sin Eleasa, tega sin Azel.',
        38: 'In Azel je imel šest sinov, katerih imena so ta: Azrikam, Bokeru, Izmael, Searija, Obadija in Hanan. Vsi ti so bili sinovi Azelovi.',
        39: 'In sinovi Eseka, njegovega brata: Ulam, prvenec njegov, Jeuš, drugi, in Elifelet, tretji.',
        40: 'In sinovi Ulamovi so bili hrabri junaki, lokostrelci, in so imeli mnogo otrok in vnukov, sto in petdeset. Vsi ti so bili od sinov Benjaminovih.',
    },
    9: {
        1: 'In ves Izrael je bil zaznamovan v rodopisih; in glej, zapisani so v knjigo kraljev Izraelovih. In Juda je bil preseljen v ujetništvo v Babilon zaradi nezvestobe svoje.',
        2: 'Prvi prebivalci pa, ki so bivali na svojih posestvih, v svojih mestih, so bili Izraelci, duhovniki, leviti in Netinimci.',
        3: 'In v Jeruzalemu so prebivali od sinov Judovih in od sinov Benjaminovih in od sinov Efraimovih in Manasejevih:',
        4: 'Utaj, sin Amihuda, sinu Omrija, sinu Imrija, sinu Banija, iz sinov Pereza, sina Judovega.',
        5: 'In od Silonovih: Asaja, prvenec, in njegovi sinovi.',
        6: 'In od sinov Zerahovih: Jeguel in bratje njegovi, šeststo in devetdeset.',
        7: 'In od sinov Benjaminovih: Salu, sin Mesulama, sinu Hodavija, sinu Hasenuva,',
        8: 'in Ibneja, sin Jerohamov, in Ela, sin Uzija, sinu Mikrijevega, in Mesulam, sin Sefatija, sinu Reguela, sinu Ibnija,',
        9: 'in njih bratje po svojih rodovih, devetsto in šestinpetdeset. Vsi ti možje so bili zarodniki v hišah očetov svojih.',
        10: 'In od duhovnikov: Jedaja, Jehojarib in Jakin,',
        11: 'in Azarija, sin Hilkija, sinu Mesulama, sinu Zadoka, sinu Merajota, sinu Ahituba, poglavar v hiši Božji,',
        12: 'in Adaja, sin Jerohama, sina Pashurja, sina Malkija, in Masaj, sin Adiela, sinu Jahzerja, sinu Mesulama, sinu Mesilemita, sinu Imerja;',
        13: 'in njih bratje, poglavarji svojim očetovskim hišam, sedemnajststo in šestdeset, jako vrli možje v opravilu službe v hiši Božji.',
        14: 'In od levitov: Semaja, sin Hašuba, sinu Azrikama, sinu Hasabija, od sinov Merarijevih;',
        15: 'in Bakbakar, Heres, Galal, Matanija, sin Miha, sinu Zihrija, sinu Asafa,',
        16: 'in Obadija, sin Semaja, sinu Galala, sinu Jedutuna, in Berekija, sin Asa, sinu Elkana, ki je prebival v vaseh Netofatčanov.',
        17: 'In vratarji: Salum, Akub, Talmon, Ahiman in njih bratje; Salum je bil načelnik.',
        18: 'In doslej čuvajo ob kraljevih vratih proti vzhodu. Oni so bili vratarji tabora sinov Levijevih.',
        19: 'In Salum, sin Korejev, sinu Ebiasafa, sinu Koraha, in bratje njegovi od hiše očeta njegovega, Korahovci, so oskrbovali službo kot varuhi na pragu šatora; in njih očetje so bili nad taboriščem Gospodovim, varuhi pri vhodu.',
        20: 'Pinehas pa, sin Eleazarjev, jim je bil svoje dni glavar; Gospod je bil ž njim.',
        21: 'Zeharija, sin Meselemija, je bil varuh pri vratih shodnega šatora.',
        22: 'Vseh teh, izbranih za varuhe ob vratih, je bilo dvesto in dvanajst. Ti so bili vpisani v rodovnike v svojih vaseh; David in Samuel, videc, jih je postavil v službo zaradi njih zvestobe.',
        23: 'Oni in njih sinovi so imeli nadzorstvo pri vratih hiše Gospodove, ob hiši šatora, kot straže.',
        24: 'Proti štirim vetrovom so stali vratarji, proti vzhodu, zahodu, severu in jugu.',
        25: 'In njih bratje v svojih vaseh so morali prihajati vsak sedmi dan, vrsteč se, da bodo ž njimi;',
        26: 'zakaj tisti štirje načelniki straže, ki so bili leviti, so imeli določeno službo in so bili nad hrami in nad zakladi v hiši Božji.',
        27: 'In prenočevali so okoli hiše Božje, ker jih je vezalo straženje, in dolžni so bili od pirati vsako jutro.',
        28: 'In nekaterim od njih je bilo streči službenim posodam, zakaj po številu so se prinašale in po številu odnašale.',
        29: 'Nekateri od njih pa so bili nastavljeni za orodje in za vse priprave svetišča in za belo moko in za vino in olje in kadilo in za dišave.',
        30: 'In nekateri sinovi duhovnikov so mešali mazilo iz dišav.',
        31: 'In Matitiju, izmed Levitov – on je bil prvenec Saluma Korahovca – je bilo poverjeno, kar se je peklo v ponvi.',
        32: 'In nekateri njih bratov, sinov Kahatovcev, so skrbeli za vrstitev kruhov, da jih pripravljajo vsako soboto.',
        33: 'Oni pa, pevci, poglavarji levitskih očetovin, so prebivali, druge službe prosti, v hramih, kajti njih služba jih je vezala po dne in po noči.',
        34: 'Ti so bili poglavarji očetovin levitskih, po svojih rodovinah, načelniki; ti so prebivali v Jeruzalemu.',
        35: 'V Gibeonu pa so prebivali: oče Gibeonov, Jegiel, čigar ženi je bilo ime Maaka;',
        36: 'in prvenec njegov Abdon, potem Zur, Kis, Baal, Ner, Nadab,',
        37: 'Gedor, Ahio, Zeharija in Miklot.',
        38: 'In Miklot je rodil Simeama. Tudi ti so prebivali pri svojih bratih v Jeruzalemu, bratom svojim nasproti.',
        39: 'In Ner je rodil Kisa, in Kis je rodil Savla, Savel pa je rodil Jonatana in Malhisua, in Abinadaba in Esbaala.',
        40: 'In sin Jonatanov je bil Merib-baal, in Merib-baal je rodil Miha.',
        41: 'In sinovi Mihovi: Piton in Melek in Tahrea in Ahaz.',
        42: 'Ahaz pa je rodil Jara, in Jara je rodil Alemeta in Azmaveta in Zimrija, Zimri pa je rodil Moza,',
        43: 'Moza je rodil Binea, tega sin je bil Refaja, tega sin Eleasa, tega sin Azel;',
        44: 'Azel pa je imel šest sinov, katerih imena so ta: Azrikam, Bokeru, Izmael, Searija, Obadija in Hanan: ti so bili sinovi Azelovi.',
    },
    10: {
        1: 'Filistejci pa so se bojevali z Izraelom; in možje Izraelovi so zbežali pred Filistejci in so padali pobiti na gorovju Gilboi.',
        2: 'In Filistejci so bili trdo za petami Savlu in sinom njegovim, in Filistejci so pobili Jonatana, Abinadaba in Malhisua, sinove Savlove.',
        3: 'In bitka je hudo pritiskala na Savla, in lokostrelci so ga dohiteli, in trepetal je pred strelci.',
        4: 'Tedaj veli Savel svojemu oprodi: Izderi meč svoj in me ž njim prebodi, da ne pridejo ti neobrezanci ter si smeh napravijo z menoj. Ali njegov oproda ni hotel, ker se je silno bal. Zato vzame Savel meč svoj in se nasadi nanj.',
        5: 'Ko pa vidi njegov oproda, da je Savel mrtev, se nasadi tudi on na svoj meč in umre.',
        6: 'Tako je umrl Savel in trije sinovi njegovi; in vsa družina njegova je umrla skupaj.',
        7: 'Ko so pa videli možje Izraelovi, ki so bili v dolini, da bežé ter da so Savel in sinovi njegovi mrtvi, zapuste svoja mesta in zbeže. In Filistejci so prišli in se nastanili v njih.',
        8: 'Zgodi se pa drugi dan, ko pridejo Filistejci slačit pobite, da najdejo Savla in sinove njegove na gorovju Gilboi.',
        9: 'In ga slečejo ter vzemo glavo njegovo in orožje njegovo in pošljejo po deželi Filistejcev kroginkrog, da se ta vesela vest oznani njih malikom in ljudstvu.',
        10: 'In orožje njegovo razpoložé v hiši bogov svojih, njegovo lobanjo pa pribijejo v hiši Dagonovi.',
        11: 'Ko so pa slišali vsi v Gileadskem Jabesu vse, kar so bili storili Filistejci Savlu,',
        12: 'se vzdignejo vsi vojščaki in vzamejo truplo Savlovo in trupla sinov njegovih in jih prineso v Jabes. In pokopali so njih kosti pod hrastom v Jabesu in se postili sedem dni.',
        13: 'In tako je umrl Savel v nezvestobi svoji, ki se je ž njo izneveril Gospodu, zoper besedo Gospodovo, ki je ni izpolnil, pa tudi zato, ker je poiskal rotilko mrtvih, da jo je vprašal,',
        14: 'Gospoda pa ni vprašal. Zato ga je usmrtil in naklonil je kraljestvo Davidu, sinu Jesejevemu.',
    },
    11: {
        1: 'Tedaj se zbere ves Izrael pri Davidu v Hebronu in reko: Glej, kost smo tvoja in meso tvoje.',
        2: 'In v prejšnjih časih, ko je kraljeval Savel, si vodil ti ven in noter Izraela; in Gospod, Bog tvoj, je rekel tebi: Ti boš pasel ljudstvo moje Izraela in ti bodeš vojvoda ljudstvu mojemu Izraelu.',
        3: 'Tako so prišli vsi starejšine Izraelovi h kralju v Hebron, in David je sklenil zavezo ž njimi v Hebronu pred Gospodom. In pomazilili so Davida za kralja Izraelu, soglasno z besedo Gospodovo po Samuelu.',
        4: 'In David in ves Izrael so šli v Jeruzalem (to je Jebus); ondi so bili Jebusejci, prebivalci dežele.',
        5: 'In prebivalci v Jebusu so rekli Davidu: Ne prideš sem noter. Vendar pa je David zavzel grad Sion, to je mesto Davidovo.',
        6: 'In David je rekel: Kdorkoli udari Jebusejce prvi, bode poglavar in poveljnik. In Joab, sin Zervijin, je zlezel gori prvi, in postal je poglavar.',
        7: 'In David se je nastanil v gradu, zato so ga imenovali mesto Davidovo.',
        8: 'In obzidal je mesto, od Mila in krog, do koder je segalo. Joab pa je popravil drugo po mestu.',
        9: 'In David je bolj in bolj napredoval, zakaj Gospod nad vojskami je bil ž njim.',
        10: 'Ti pa so prvi izmed junakov, ki jih je imel David in ki so mu bili vrli pomočniki v kraljestvu njegovem z vsem Izraelom vred, da ga postavijo za kralja po besedi Gospodovi o Izraelu.',
        11: 'In to je število junakov, ki jih je imel David: Jasobeam, sin Hakmonija, prvi iz tridesetih; on je vzdignil sulico svojo zoper tristo in jih je pobil naenkrat.',
        12: 'In za njim je bil Eleazar, sin Dodov, Ahohovec, eden izmed treh junakov.',
        13: 'On je bil z Davidom v Pasdamimu, in ondi so bili Filistejci zbrani na boj; bil pa je tam kos njive, poln ječmena, in ljudstvo je bežalo izpred Filjstejcev.',
        14: 'In postavita se sredi zemljišča in ga obranita ter pobijeta Filistejce; in Gospod jih je rešil z zmago veliko.',
        15: 'In trije izmed tridesetih načelnikov so šli doli v skalo k Davidu, v Adulamsko votlino; in vojska Filistejcev je bila utaborjena v dolini Rafaimov.',
        16: 'In David je bil takrat v trdnjavi, in straža Filistejcev je takrat bila v Betlehemu.',
        17: 'In Davida je obšla želja in je rekel: O da bi mi kdo dal piti vode iz studenca v Betlehemu, ki je pri vratih!',
        18: 'In ti trije so predrli skozi tabor Filistejcev in zajeli vode iz studenca v Betlehemu, ki je bil pri vratih, in so jo vzeli in prinesli Davidu. A David je ni hotel piti, temuč jo je izlil kot daritev Gospodu',
        19: 'in je rekel: Bog mi ne daj, da bi to storil! Naj li pijem kri teh mož, ki so vnemar pustili življenje svoje? kajti z nevarnostjo svojega življenja so jo prinesli sem! Zato je ni hotel piti. To so storili ti trije junaki.',
        20: 'In Abisaj, brat Joabov, je bil glava drugim trem; zakaj mahnil je s sulico svojo po treh sto in jih je pobil; in imel je sloveče ime med temi tremi.',
        21: 'Izmed teh treh druge vrste je bil najbolj slaven in jim je postal poveljnik; toda prvih treh ni dosegel.',
        22: 'Benaja, sin Jojadov, sin hrabrega; moža iz Kabzeela, ki je bil storil velika dela, ta je ubil dva sina Ariela iz Moaba; ta je stopil tudi doli v jamo in ubil leva v njej, ko je bil sneg.',
        23: 'In ubil je Egipčana, moža visoke postave, pet komolcev dolgega, in Egipčan je imel v roki sulico kakor tkalčje vratilo, a on je šel doli k njemu s palico in iztrgal sulico Egipčanu iz roke ter ga prebodel z lastno sulico njegovo.',
        24: 'To je storil Benaja, sin Jojadov, in je imel sloveče ime med temi tremi junaki.',
        25: 'Glej, on je bil slavnejši nego tistih trideset, ali prvih treh ni dosegel; in David ga je postavil med svoje svetovalce.',
        26: 'In junaki v vojskah so bili: Asahel, brat Joabov, Elhanan, sin Dodov iz Betlehema,',
        27: 'Samot Harorčan, Helez Pelonjan,',
        28: 'Ira, sin Ikešev, Tekojčan, Abiezer Anatotčan,',
        29: 'Sibekaj Husajec, Ilaj Ahohovec,',
        30: 'Maharaj Netofatčan, Heled Netofatčan, sin Baanov,',
        31: 'Itaj, sin Ribajev iz Gibee sinov Benjaminovih, Benaja Piratončan,',
        32: 'Huraj od potokov v Gaasu, Abiel Arbatski,',
        33: 'Azmavet Baharumčan, Eljahba Salbončan,',
        34: 'sinovi Hasema Gizonca, Jonatan, sin Sageja Hararovca,',
        35: 'Ahiam, sin Sakarja Hararovca, Elifal, sin Urov,',
        36: 'Hefer Mekerajec, Ahija Pelonjan,',
        37: 'Hezro Karmelčan, Naaraj, sin Ezbajev,',
        38: 'Joel, brat Natanov, Mibhar, sin Hagrijev,',
        39: 'Zelek Amonec, Naharaj Berotčan, oproda Joaba, sinu Zervijinega,',
        40: 'Ira Jitričan, Gareb Jitričan,',
        41: 'Urija Hetejec, Zabad, sin Ahlajev,',
        42: 'Adina, sin Sizov, Rubenovec, načelnik Rubenovcev in tridesetih ž njim,',
        43: 'Hanan, sin Maake, Josafat Mitnejec,',
        44: 'Uzija Astarotčan, Sama in Jegiel, sinova Hotama Aroerskega,',
        45: 'Jediael, sin Simrijev, in brat njegov Joha Tizijčan,',
        46: 'Eliel Mahavim, Jeribaj in Josavija, sinova Elnaama, in Itma Moabec,',
        47: 'Eliel in Obed in Jaasiel Mezobajan.',
    },
    12: {
        1: 'In ti so, ki so prišli k Davidu v Ziklag, ko se je še skrival pred Savlom, sinom Kisovim; in bili so tudi med junaki, ki so mu pomagali v boju,',
        2: 'oboroženi z loki, in so z desno in levo roko s prač metali kamenje in pšice streljali z loka; bili so pa od bratov Savlovih, iz Benjamina.',
        3: 'Načelnik jim je bil Ahiezer, potem Joas, sinova Semaa Gibeatčana; Jeziel in Pelet, sinova Azmavetova; Beraka in Jehu Anatotčan,',
        4: 'Ismaja Gibeončan, korenjak med tridesetimi in njih poveljnik; Jeremija, Jahaziel, Johanan, Jozabad Gederčan;',
        5: 'Eluzaj, Jerimot, Bealija, Semarija, Sefatija Harufjan;',
        6: 'Elkana, Išija, Azarel, Joezer in Jasobeam, Korahovci;',
        7: 'in Joela in Zebadija, sinova Jerohama iz Gedorja.',
        8: 'Tudi izmed Gadovcev so se ločili nekateri, da bi bili z Davidom na trdnjavi v puščavi, hrabri junaki, izurjeni za vojsko, ki so bili spretni s ščitom in sulico, katerih obličja so bila kakor levja in ki so bili hitri kakor srne v gorah:',
        9: 'Ezer, prvi, Obadija, drugi, Eliab, tretji,',
        10: 'Mismana, četrti, Jeremija, peti,',
        11: 'Ataj, šesti, Eliel, sedmi,',
        12: 'Johanan, osmi, Elzabad, deveti,',
        13: 'Jeremija, deseti, Makbanaj, enajsti.',
        14: 'Ti, izmed sinov Gadovih, so bili poveljniki vojski; najmanjšega je bilo šteti za sto, največjega pa za tisoč.',
        15: 'Ti so, ki so šli čez Jordan v prvem mesecu, kadar navadno stopa čez vse svoje bregove, in zapodili so v beg vse prebivalce po dolinah, proti jutru in proti zahodu.',
        16: 'In prišli so nekateri iz sinov Benjaminovih in Judovih v trdnjavo k Davidu.',
        17: 'In David jim gre ven naproti in izpregovori ter jim reče: Ako ste prišli v miru k meni, da mi pomagate, se sklene srce moje z vami; ako ste pa prišli izdajat me mojim nasprotnikom, ko vendar ni krivice v rokah mojih, poglej to očetov naših Bog in kaznuj!',
        18: 'Tedaj pride duh nad Amasaja, ki je bil poglavar med trideseterimi, in reče: Tvoji smo, David, in na tvoji strani, sin Jesejev! Mir, mir bodi tebi in mir tvojim pomočnikom, kajti Bog tvoj ti pomaga! Nato jih David sprejme in jih postavi za poglavarje trumi.',
        19: 'Od Manaseja so tudi nekateri uskočili k Davidu, ko je prišel s Filistejci bojevat se zoper Savla, a ni jim smel pomagati, zakaj knezi Filistejcev so ga odslovili, ko so se bili posvetovali, rekoč: Za glavo bi nam šlo, ko bi uskočil h gospodu svojemu Savlu!',
        20: 'Ko je nato šel v Ziklag, so uskočili k njemu od Manaseja: Adnah, Jozabad, Jediael, Mihael, Jozabad, Elihu in Ziletaj, poveljniki tisočim Manasejevim.',
        21: 'In pomagali so Davidu zoper roparske čete, zakaj vsi so bili hrabri junaki; in postali so vojni poveljniki.',
        22: 'Dan za dnevom so namreč prihajali nekateri k Davidu mu pomagat, da je bila velika vojska, kakor vojska Božja.',
        23: 'In to so števila glav tistih, ki so bili oboroženi za vojsko in so prišli k Davidu v Hebron, da mu naklonijo kraljestvo Savlovo po povelju Gospodovem.',
        24: 'Sinov Judovih, ki so nosili ščit in sulico, jo bilo šest tisoč osemsto, oboroženih za vojsko.',
        25: 'Od sinov Simeonovih: vrlih junakov za vojsko sedem tisoč in sto.',
        26: 'Od sinov Levijevih: štiri tisoč in šeststo.',
        27: 'In Jojada je bil vojvoda med Aronovimi in ž njim jih je bilo tri tisoč in sedemsto;',
        28: 'in Zadok mladenič, hrabri junak, in iz družine očeta njegovega dvajsetindva poveljnika.',
        29: 'In od sinov Benjaminovih, bratov Savlovih: tri tisoč; kajti do takrat se je večina zvesto držala hiše Savlove.',
        30: 'In od sinov Efraimovih: dvajset tisoč in osemsto hrabrih junakov in slovečih mož v hišah očetov svojih.',
        31: 'In od polovice rodu Manasejevega: osemnajst tisoč, ki so bili določeni po imenih, naj gredo in postavijo Davida za kralja.',
        32: 'In od sinov Isaharjevih: možje, ki so imeli razsodnost glede časov, da bi vedeli, kaj ima Izrael storiti, njih poglavarjev je bilo dvesto, in vsi njih bratje so bili pod njih poveljem.',
        33: 'Od Zebulona tistih, ki so hodili na vojsko in se postavljali v bojne vrste z raznovrstnim vojnim orožjem, je bilo petdeset tisoč, pripravljenih, uvrstiti se v boj z nerazdeljenim srcem.',
        34: 'In od Neftalija tisoč poveljnikov, in ž njimi nosečih ščit in sulico sedemintrideset tisoč.',
        35: 'In od Danovcev, zmožnih, postaviti se v bojne vrste: osemindvajset tisoč in šeststo.',
        36: 'In od Aserja štirideset tisoč, zmožnih iti na vojsko, da se postavijo v bojne vrste.',
        37: 'In z druge strani Jordana, od Rubenovcev in Gadovcev in od polovice rodu Manasejevega, z raznovrstnim bojnim orožjem: stoindvajset tisoč.',
        38: 'Vsi ti vojščaki, zmožni, postaviti se v bojne vrste, so prišli z nerazdeljenim srcem v Hebron, da postavijo Davida za kralja vsemu Izraelu. Pa tudi vsi drugi v Izraelu so bili enega srca, da postavijo Davida za kralja.',
        39: 'In bili so tam pri Davidu tri dni, in jedli so in pili, kajti njih bratje so jim bili pripravili.',
        40: 'Tudi so prinesli tisti, ki so bivali bliže, celó od Isaharja, Zebulona in Neftalija, na oslih in na velblodih in na mezgih in na volih kruha in močnatih jedi, gruče smokev, suhega grozdja, vina in olja, govedi in drobnice obilo; kajti radost je bila v Izraelu.',
    },
    13: {
        1: 'In David se je posvetoval s poveljniki čez tisoč in čez sto, z vsemi vojvodami.',
        2: 'In David reče vsemu zboru Izraelovemu: Ako se vam zdi prav in ako je ta stvar od Gospoda, našega Boga, pošljimo povsod k ostalim bratom našim po vseh pokrajinah Izraelovih in ž njimi vred k duhovnikom in levitom, ki so v mestih okrajev svojih, da naj se zbero k nam.',
        3: 'In prinesimo skrinjo Boga svojega sem k sebi; kajti nismo vprašali po njej v dnevih Savlovih.',
        4: 'In ves zbor je dejal, naj se to stori, zakaj stvar se je videla dobra vsemu ljudstvu.',
        5: 'Zbral je torej David vse Izraelce od Sihorja, potoka egiptovskega, tja do vhoda v Hamat, da preneso skrinjo Božjo iz Kirjat-jearima.',
        6: 'In David in vsi Izraelci so šli gori v Baalo, v Kirjat-jearim, ki je na Judovem, da prineso odondod skrinjo Boga, Gospoda, ki stoluje nad kerubi, kjer se kliče njegovo ime.',
        7: 'In peljali so skrinjo Božjo na novem vozu iz hiše Abinadabove. Uza in Ahio pa sta vodila voz.',
        8: 'In David in ves Izrael so igrali pred Bogom na vso moč s petjem, na harfe in na strune in na bobne in cimbale in na trombe.',
        9: 'In ko so prišli h gumnu Kidonovemu, je iztegnil Uza roko, da pridrži skrinjo, kajti volom se je izpoddrsnilo.',
        10: 'In vname se jeza Gospodova zoper Uza in ga udari, ker je iztegnil roko svojo po skrinji; in umrl je tam pred Bogom.',
        11: 'In David je bil žalosten, ker je bil Gospod napravil pretrg z Uzom, in imenoval je ta kraj Perez Uza, do današnjega dne.',
        12: 'In David se zboji Gospoda tisti dan in reče: Kako naj pripeljem skrinjo Božjo k sebi?',
        13: 'David torej ni odpravil skrinje k sebi v mesto Davidovo, temuč je krenil ž njo v hišo Obededoma Gatovca.',
        14: 'In skrinja Božja je ostala z družino Obededomovo v hiši njegovi tri mesece; in Gospod je blagoslovil hišo Obededomovo in vse, kar je imel.',
    },
    14: {
        1: 'In Hiram, kralj v Tiru, je poslal poslance k Davidu in cedrovega lesa in zidarje in tesarje, da mu zgrade hišo.',
        2: 'In David je zaznal, da ga je Gospod potrdil za kralja nad Izraelom, kajti kraljestvo njegovo je bilo visoko povišano zaradi ljudstva njegovega Izraela.',
        3: 'In David si je vzel še več žen v Jeruzalemu; in David je rodil še več sinov in hčer.',
        4: 'In ta so imena otrok, ki jih je imel v Jeruzalemu: Samua, Sobab, Natan in Salomon,',
        5: 'Ibhar, Elisua, Elpelet,',
        6: 'Noga, Nefeg, Jafija,',
        7: 'Elisama, Beeliada in Elifelet.',
        8: 'Ko so pa Filistejci slišali, da je bil David pomaziljen za kralja nad vsem Izraelom, pridejo vsi Filistejci gori iskat Davida. In ko je David zvedel za to, jim je šel naproti.',
        9: 'Filistejci so pa prišli in se razgrnili po dolini Refaimov.',
        10: 'In David je vprašal Boga, rekoč: Ali naj grem gori zoper Filistejce? In mi jih li hočeš dati v roko? In Gospod mu veli: Pojdi gori, kajti dam ti jih v roko!',
        11: 'Oni pa so prišli v Baalperazim, in David jih porazi ondi. In David reče: Gospod je raztrgal sovražnike moje po moji roki, kakor vode pretrgajo jez. Zato so dali ime tistemu kraju Baalperazim.',
        12: 'Popustili so pa svoje bogove tamkaj. In David ukaže, in sežgali so jih v ognju.',
        13: 'In Filistejci so zopet pridrli in se razgrnili po dolini.',
        14: 'David pa zopet vpraša Boga, in Bog mu reče: Ne hodi gori za njimi, kreni od njih in pojdi nadnje od strani murvovih dreves.',
        15: 'In ko začuješ šumenje iz vrhov murvovih dreves, kakor da prihaja vojska, tedaj pojdi ven v boj: zakaj Bog gre pred teboj, da udari vojsko Filistejcev.',
        16: 'In David je storil, kakor mu je bil zapovedal Bog, in pobijali so vojsko Filistejcev od Gibeona do Gezerja.',
        17: 'In Davidovo ime se je razglasilo po vseh deželah, in Gospod je spravil v strah pred njim vse narode',
    },
    15: {
        1: 'In David si je sezidal hiše v mestu Davidovem; in pripravil je mesto za skrinjo Božjo in razpel šator zanjo.',
        2: 'Tedaj je rekel David: Nihče ne sme nositi skrinje Božje razen levitov, kajti nje je izvolil Gospod, da nosijo skrinjo Božjo in služijo njemu vekomaj.',
        3: 'In David zbere vsega Izraela v Jeruzalemu, da prineso skrinjo Gospodovo na mesto njeno, ki ga je bil pripravil zanjo.',
        4: 'David zbere tudi sinove Aronove in levite.',
        5: 'Iz sinov Kahatovih: Uriela, poglavarja, in njegovih bratov sto in dvajset;',
        6: 'iz sinov Merarijevih: Asaja, poglavarja, in njegovih bratov dvesto in dvajset;',
        7: 'iz sinov Gersomovih: Joela, poglavarja, in njegovih bratov sto in trideset;',
        8: 'iz sinov Elizafanovih: Semaja, poglavarja, in njegovih bratov dvesto;',
        9: 'iz sinov Hebronovih: Eliela, poglavarja, in njegovih bratov osemdeset;',
        10: 'iz sinov Uzielovih: Aminadaba, poglavarja, in bratov njegovih sto in dvanajst.',
        11: 'In David pokliče Zadoka in Abiatarja, duhovnika, in levite, namreč Uriela, Asaja, Joela, Semaja, Eliela in Aminadaba,',
        12: 'in jim veli: Vi ste poglavarji očetovinam levitov: posvetíte se vi in bratje vaši, da prinesete gori skrinjo Gospoda, Boga Izraelovega, na mesto, ki sem ga pripravil zanjo.',
        13: 'Zakaj ker je niste nosili onikrat, je storil Gospod, naš Bog, pretrg med nami, ker ga nismo iskali, kakor je prav.',
        14: 'Posvetili so se torej duhovniki in leviti, da prineso gori skrinjo Gospoda, Boga Izraelovega.',
        15: 'In sinovi Levijevi so nesli skrinjo Božjo na ramah, zadevši nase droga njena, kakor je bil zapovedal Mojzes po besedi Gospodovi.',
        16: 'In David je velel poglavarjem levitov, naj postavijo svoje brate, pevce, z glasbenim orodjem, s psalmovimi citrami, s harfami in cimbali, da glasno pojo, povzdigujoč glas z veseljem.',
        17: 'Nastavili so torej leviti Hemana, sina Joelovega, in od bratov njegovih Asafa, sina Berekijevega, in od sinov Merarijevih brate svoje: Etana, sina Kusajevega,',
        18: 'in ž njimi njih brate druge vrste: Zeharija, Bena, Jaaziela, Semiramota, Jehiela, Unija, Eliaba, Benaja, Maaseja, Matitija, Elifeleha, Mikneja, Obededoma in Jegiela, vratarje; –',
        19: 'in sicer pevce, Hemana, Asafa in Etana, da glasno godejo na medene cimbale;',
        20: 'Zeharija pa in Aziela, Semiramota, Jehiela, Unija, Eliaba, Maaseja in Benaja s psalmovimi citrami na visoke glasove;',
        21: 'Matitija pa in Elifeleha, Mikneja, Obededoma, Jegiela, Azazija, s harfami na globoke glasove, da vodijo petje.',
        22: 'In Kenanija je bil načelnik levitom pri petju; on je učil petje, ker je bil veščak.',
        23: 'In Berekija in Elkana sta bila vratarja pri skrinji.',
        24: 'A Sebanija, Josafat, Netanel, Amasaj, Zeharija, Benaja in Eliezer, duhovniki, so trobili na trombe pred skrinjo Božjo. In Obededom in Jehia sta bila vratarja pri skrinji.',
        25: 'David in starejšine Izraelovi in poveljniki tisočim so torej šli, da prineso gori skrinjo zaveze Gospodove iz hiše Obededomove z veseljem.',
        26: 'In ker je Bog pomagal levitom, ki so nesli skrinjo zaveze Gospodove, so darovali sedem juncev in sedem ovnov.',
        27: 'David pa je bil oblečen v vrhnjo suknjo iz tenčice in tudi vsi leviti, ki so nesli skrinjo, in pevci in Kenanija, pevovodja, pri pevcih; in David je imel na sebi platnen naramnik.',
        28: 'Tako je ves Izrael prenesel gori skrinjo Gospodove zaveze z veselim ukanjem in z glasom roga in s trobentami in cimbali, z glasnim petjem pri psalmovih citrah in harfah.',
        29: 'In ko je prišla skrinja zaveze Gospodove v mesto Davidovo, je gledala Mihala, hči Savlova, skozi okno, in videč kralja Davida, da poskakuje in igra, ga je zaničevala v srcu svojem.',
    },
    16: {
        1: 'In prinesli so skrinjo Božjo noter ter jo postavili sredi šatora, ki ga je bil David razpel zanjo; in darovali so žgalne in mirovne daritve pred Bogom.',
        2: 'In ko je David končal darovanje žgalščin in mirovnih žrtev, je blagoslovil ljudstvo v imenu Gospodovem;',
        3: 'in je razdelil za vsakega izmed Izraela, moža in ženo, da je vsakdo dobil hleb kruha in kos mesa in suhega grozdja.',
        4: 'In postavil je nekatere iz levitov za strežnike pred skrinjo Gospodovo, da naj s hvalo spominjajo in zahvaljujejo in slavijo Gospoda, Boga Izraelovega:',
        5: 'Asafa, načelnika, in Zeharija, drugega po njem, Jegiela, Semiramota, Jehiela, Matitija, Eliaba, Benaja, Obededoma in Jegiela, s psalmovimi citrami in s harfami, in Asafa s cimbali, da glasno gode,',
        6: 'in Benaja in Jahaziela, duhovnika, s trobentami, da stojita vedno pred skrinjo zaveze Gospodove.',
        7: 'Tedaj je, tisti dan, David v prvič ukazal Asafu in bratom njegovim, naj hvalijo Gospoda:',
        8: 'Hvalite Gospoda, kličite ime njegovo, oznanjujte med ljudstvi dejanja njegova!',
        9: 'Pojte mu, psalme mu prepevajte, govorite o vseh čudovitih delih njegovih!',
        10: 'Hvalite se v svetem imenu njegovem; veseli se naj srce njih, ki iščejo Gospoda!',
        11: 'Iščite Gospoda in moči njegove, iščite vedno obličje njegovo!',
        12: 'Spominjajte se čudes njegovih, ki jih je storil, čudovitih znamenj in razsodkov ust njegovih;',
        13: 'o seme Izraela, njegovega hlapca, otroci Jakobovi, izvoljenci njegovi!',
        14: 'On, Gospod, je Bog naš, po vsej zemlji se vrše sodbe njegove.',
        15: 'Spominjajte se vekomaj zaveze njegove, besede, katero je zapovedal tisoč rodovom,',
        16: 'zaveze, ki jo je sklenil z Abrahamom, in njegove prisege Izaku,',
        17: 'ki jo je potrdil Jakobu za postavo, Izraelu za večno zavezo,',
        18: 'gororeč: Tebi hočem dati deželo Kanaansko kot vam odmerjeno dedno posest!',
        19: 'ko vas je bilo po številu še malo, prav malo, in ste kot tujci bivali v njej;',
        20: 'in so hodili od naroda do naroda in iz enega kraljestva k drugemu ljudstvu.',
        21: 'Ni jih dovolil zatirati nikomur, še kralje je strahoval zaradi njih:',
        22: '„Ne doteknite se maziljencev mojih in ne storite žalega prorokom mojim!“',
        23: 'Pojte Gospodu, vsa zemlja, veselo oznanjajte od dne do dne zveličanje njegovo!',
        24: 'Pripovedujte med poganskimi narodi veličastvo njegovo, med vsemi ljudstvi čudovita dela njegova!',
        25: 'Kajti velik je Gospod in velike hvale vreden, strašen je on nad vse bogove.',
        26: 'Zakaj vsi bogovi ljudstev so ničevi maliki, Gospod pa je naredil nebesa.',
        27: 'Slava in lepota sta pred njim, moč in radost v mestu njegovem.',
        28: 'Dajajte Gospodu, ljudstev rodovine, dajajte Gospodu čast in moč!',
        29: 'Dajajte Gospodu slavo imena njegovega, prinesite dar in pridite pred obličje njegovo; klanjajte se Gospodu v diki svetosti.',
        30: 'Trepetajte pred njim, vsa zemlja! Zemlje obod je tudi utrjen, da ne omahne.',
        31: 'Veselé se naj nebesa in raduj se zemlja, in govore naj med narodi: Gospod kraljuje!',
        32: 'Grmi naj morje in kar je v njem, raduj se polje in vse, kar je na njem!',
        33: 'Tedaj bo veselo pevalo vse drevje v gozdu pred obličjem Gospodovim, kajti prihaja sodit zemljo!',
        34: 'Hvalite Gospoda, ker je dobrotljiv, ker vekomaj traja milost njegova!',
        35: 'In recite: Reši nas, o Bog zveličanja našega, in zberi nas in otmi poganov, da hvalimo sveto ime tvoje in se veličamo v hvali tvoji.',
        36: 'Slava Gospodu, Bogu Izraelovemu, od vekomaj do vekomaj! In vse ljudstvo je dejalo: Amen! in je hvalilo Gospoda.',
        37: 'Postavil je torej tam pred skrinjo zaveze Gospodove Asafa in brate njegove, da strežejo vedno pred skrinjo, kolikor je bilo treba vsak dan;',
        38: 'in Obededoma ž njegovimi brati, oseminšestdeset, tudi Obededoma, sina Jedutunovega, in Hosa, da sta vratarja;',
        39: 'Zadoka pa, duhovnika, in brate njegove, duhovnike, pred prebivališčem Gospodovim na višavi, ki je bila v Gibeonu,',
        40: 'da darujejo žgalne žrtve Gospodu na žgalnem oltarju vsekdar zjutraj in zvečer, po vsem, kar je pisano v zakonu Gospodovem, ki ga je zapovedal Izraelu;',
        41: 'in ž njimi Hemana in Jedutuna in druge, kar jih je bilo izbranih, ki so bili zaznamenovani po imenih, da bi hvalili Gospoda, ker vekomaj traja milost njegova;',
        42: 'in ž njimi Hemana in Jedutuna s trompetami in cimbali za tiste, ki jim je bilo glasno igrati, in z glasbenim orodjem v hvalo Božjo; in sinom Jedutunovim je bilo stati pri vratih.',
        43: 'In vse ljudstvo se je razšlo, vsak v hišo svojo; in David se je vrnil, da blagoslovi hišo svojo.',
    },
    17: {
        1: 'In zgodi se, ko je David prebival v hiši svoji, da reče Natanu proroku: Glej, jaz stanujem v cedrovi hiši, a skrinja zaveze Gospodove prebiva pod preprogami.',
        2: 'In Natan reče Davidu: Stori vse, kar ti je v srcu, kajti Bog je s teboj!',
        3: 'Še to noč pa pride beseda Gospodova k Natanu, govoreč:',
        4: 'Pojdi in reci hlapcu mojemu Davidu: Tako pravi Gospod: Ne boš mi ti gradil hiše, da prebivam v njej.',
        5: 'Saj nisem prebival v hiši od dne, ko sem pripeljal Izraela semkaj, do današnjega dne, ampak hodil sem iz šatora v šator, iz enega bivališča v drugo.',
        6: 'Kamorkoli sem šel z vsem Izraelom, sem li besedo govoril s katerim sodnikov Izraelovih, ki sem jim zapovedal pasti ljudstvo moje, rekoč: Zakaj mi niste zgradili cedrove hiše?',
        7: 'Tako torej véli hlapcu mojemu Davidu: Tako pravi Gospod nad vojskami: Jaz sem te vzel s pašnikov, ko si hodil za ovcami, da bodeš vojvoda ljudstvu mojemu Izraelu;',
        8: 'in sem bil s teboj, kamorkoli si šel, in sem zatrl vse sovražnike tvoje pred teboj in ti storil ime kakor ime velikašev, ki so na zemlji.',
        9: 'In hočem pripraviti kraj ljudstvu svojemu Izraelu in jih zasaditi, da bodo prebivali na svojem in se več ne premikali; tudi jih ne bodo več gonobili sinovi krivice kakor poprej',
        10: 'in odkar sem zapovedal sodnikom, da bodo nad ljudstvom mojim Izraelom; in ponižam vse sovražnike tvoje. Vrhutega ti pravim, da Gospod zgradi hišo tebi.',
        11: 'Ko se ti dopolnijo dnevi, da pojdeš k očetom svojim, hočem postaviti seme tvoje za teboj, ki bode izmed sinov tvojih, in hočem utrditi kraljestvo njegovo.',
        12: 'On mi bo zgradil hišo, in jaz utrdim prestol njegov na veke.',
        13: 'Jaz mu bodem za očeta, in on mi bode za sina; in mu ne odtegnem milosti svoje, kakor sem jo odtegnil njemu, ki je bil pred teboj,',
        14: 'temuč ustanovitim ga v hiši svoji in v kraljestvu svojem za vekomaj, in prestol njegov bo utrjen vekomaj.',
        15: 'Po vseh teh besedah in po vsej tej prikazni je točno govoril Natan Davidu.',
        16: 'Tedaj stopi David noter in sede pred Gospoda in reče: Kdo sem jaz, o Gospod Bog, in kaj je hiša moja, da si me privedel tako daleč?',
        17: 'In to se je še premalo videlo tvojim očem, o Bog, in govoril si o hlapca svojega hiši za daljno prihodnost, in pogledal si me po načinu vzvišenega človeka, Gospod Bog.',
        18: 'Kaj more David še govoriti tebi zastran časti, izkazane hlapcu tvojemu? Saj ti poznaš hlapca svojega.',
        19: 'O Gospod, zaradi hlapca svojega in po srcu svojem si storil vso to velikost, da oznaniš vse te velike reči.',
        20: 'O Gospod, ni ga tebi enakega, tudi ni Boga razen tebe, po vsem, kar smo slišali na ušesa svoja.',
        21: 'In kje je edino ljudstvo na zemlji kakor ljudstvo tvoje Izrael, ki ga je šel Bog odkupit sebi za ljudstvo, da si napraviš ime z velikimi in strahovitimi rečmi, ko si pregnal narode izpred ljudstva svojega, ki si ga odkupil iz Egipta?',
        22: 'Kajti storil si ljudstvo svoje, Izraela, sebi za ljudstvo na vekomaj, in ti si, Gospod, postal njih Bog.',
        23: 'In sedaj, o Gospod: beseda, ki si jo govoril o hlapcu svojem in o hiši njegovi, ostani veljavna na vekomaj, in stóri, kakor si govoril.',
        24: 'Da, veljavna ostani in ime tvoje bodi poveličevano vekomaj, ko bodo govorili: Gospod nad vojskami, Bog Izraelov, je Bog za Izraela! In hiša tvojega hlapca Davida bodi utrjena pred teboj!',
        25: 'Zakaj ti, moj Bog, si razodel hlapcu svojemu, da mu zgradiš hišo; zato se je osrčil hlapec tvoj moliti pred teboj.',
        26: 'In sedaj, o Gospod, ti si Bog, in ti si govoril hlapcu svojemu to predobro obljubo!',
        27: 'In sedaj rači blagosloviti hlapca svojega hišo, da ostane pred teboj vekomaj; ker ti si jo, o Gospod, blagoslovil, zato bo blagoslovljena vekomaj.',
    },
    18: {
        1: 'In zgodi se potem, da je porazil David Filistejce in jih pripravil ob moč ter vzel Gat in ž njim združena mesta iz rok Filistejcev.',
        2: 'Porazil je tudi Moaba; in Moabci so postali podložni Davidu in so prinašali darove.',
        3: 'David je tudi porazil Hadarezerja, kralja v Zobi pri Hamatu, ko je šel, da si utrdi oblast pri reki Evfratu.',
        4: 'In David mu je vzel tisoč voz in sedem tisoč konjikov in dvajset tisoč pešcev; in David je ohromel vse vozne konje, ohranil jih je samo pri sto vozeh.',
        5: 'Ko pa so prišli Sirci iz Damaska pomagat Hadarezerju, kralju v Zobi, je David pobil izmed Sircev dvaindvajset tisoč mož.',
        6: 'Tedaj je David postavil posadko v Sirijo ob Damasku; in Sirci so postali podložni Davidu in so prinašali darove. Kajti Gospod je pomagal Davidu, kamorkoli je šel.',
        7: 'In David je vzel ščite iz zlata, ki so jih imeli hlapci Hadarezerjevi, in jih je prinesel v Jeruzalem.',
        8: 'Tudi iz Tibhata in iz Kuna, mest Hadarezerjevih, je David vzel veliko brona, in iz njega je napravil Salomon bronasto morje in stebra in bronaste posode.',
        9: 'Ko pa začuje Tov, kralj v Hamatu, da je David porazil vso vojsko Hadarezerja, kralja v Zobi,',
        10: 'pošlje Hadorama, sina svojega, h kralju Davidu, da ga pozdravi in mu čestita na tem, da se je bojeval zoper Hadarezerja in ga porazil (kajti Hadarezer se je vedno bojeval zoper Tova); in prinese s seboj vsakovrstne posode zlate in srebrne in bronaste.',
        11: 'Te je tudi kralj David posvetil Gospodu s srebrom in zlatom vred, kar ga je prinesel od vseh narodov: od Edomcev in Moabcev in od sinov Amonovih, od Filistejcev in od Amalekovcev.',
        12: 'In Abisaj, sin Zervijin, je porazil iz Edomcev v Solni dolini osemnajst tisoč.',
        13: 'In postavil je posadke po Edomskem, in vsi Edomci so postali podložni Davidu. Kajti Gospod je pomagal Davidu, kamorkoli je šel.',
        14: 'In David je kraljeval vsemu Izraelu in izvrševal je sodbo in pravičnost vsemu ljudstvu svojemu.',
        15: 'Joab pa, sin Zervijin, je bil nad vojsko, in Josafat, sin Ahiludov, je bil deželni letopisec;',
        16: 'in Zadok, sin Ahitubov, in Abimelek, sin Abiatarjev, sta bila duhovnika, in Savsa je bil pisar,',
        17: 'in Benaja, sin Jojadov, je bil nad Keretejci in Peletejci, in sinovi Davidovi so bili prvi pri kralju.',
    },
    19: {
        1: 'In zgodi se potem, da je umrl Nahas, kralj sinov Amonovih, in sin njegov je zakraljeval na mestu njegovem.',
        2: 'In David reče: Milost izkažem Hanunu, sinu Nahasovemu, kajti oče njegov mi je izkazal milost. Pošlje torej David sporočnike, da ga potolaži za očetom njegovim. In Davidovi hlapci pridejo v deželo sinov Amonovih k Hanunu, tolažit ga.',
        3: 'Ali knezi sinov Amonovih reko Hanunu: Meniš li, da David spoštuje očeta tvojega, ker je poslal tolažnike k tebi? Niso li prišli hlapci njegovi k tebi, da preiščejo deželo in jo ugonobe, ko jo ogledajo?',
        4: 'Hanun vzame torej hlapce Davidove in jih obrije in jim odreže polovico oblačil do ledja, in jih pošlje nazaj.',
        5: 'In nekateri so šli in povedali Davidu o tistih možeh. In pošlje jim naproti; kajti tisti možje so bili silno osramočeni. In kralj sporoči: Ostanite v Jerihu, dokler vam ne porasto brade, potem se vrnite!',
        6: 'In ko so videli sinovi Amonovi, da so se naredili mrzke Davidu, pošljejo Hanun in sinovi Amonovi tisoč talentov srebra, da si najmejo voz in konjikov iz Mezopotamije in iz Aram-Maake in iz Zobe.',
        7: 'Najeli so torej dvaintrideset tisoč voz in kralja iz Maake z moštvom njegovim; ti pridejo in se utabore pred Medebo. In sinovi Amonovi se zbero iz svojih mest in pridejo na boj.',
        8: 'Ko pa to izve David, pošlje Joaba in vso vojsko, hrabre može.',
        9: 'In sinovi Amonovi izidejo in se pripravijo za boj ob mestnih vratih; kralji pa, ki so prišli od drugod; so bili posebe na polju.',
        10: 'Ko torej Joab vidi, da je spredaj in zadaj naskok naperjen proti njemu, izbere iz vseh najboljših mož Izraelovih in jih postavi v boj zoper Sirce.',
        11: 'Ostalo ljudstvo pa da pod roko bratu svojemu Abisaju, in pripravijo se na boj zoper sinove Amonove.',
        12: 'In veli: Ako mi bodo Sirci premočni, bodi mi v pomoč; ako pa bodo sinovi Amonovi tebi premočni, pomorem ti jaz!',
        13: 'Bodi srčen in junaški se bojujva za naše ljudstvo in za mesta Boga našega, in Gospod naj stori, kar se mu vidi dobro!',
        14: 'Joab torej in ljudstvo, ki je bilo pri njem, se približa Sircem na boj, in zbeže pred njim.',
        15: 'Ko pa vidijo sinovi Amonovi, da beže Sirci, pobegnejo tudi oni pred Abisajem, bratom njegovim, in priteko v mesto. Tedaj pride Joab v Jeruzalem.',
        16: 'In ko vidijo Sirci, da so morali pobegniti pred Izraelom, pošljejo poslance in izvabijo Sirce, ki so bili onkraj reke, in Sofaha, poveljnika vojske Hadarezerjeve, ki jim je bil na čelu.',
        17: 'In to se sporoči Davidu; in zbere vsega Izraela in preide čez Jordan in pride nadnje ter se pripravi na boj ž njimi. In ko se je David postavil zoper Sirce, so se bojevali ž njim.',
        18: 'A Sirci zbeže pred Izraelom; in David je pobil izmed Sircev sedemtisoč bojevnikov na vozeh in štirideset tisoč pešcev; usmrtil je tudi Sofaha, poveljnika vojske.',
        19: 'In ko so videli hlapci Hadarezerjevi, da so bili poraženi pred Izraelom, so sklenili mir z Davidom in so mu bili podložni. In niso hoteli Sirci več pomagati sinovom Amonovim.',
    },
    20: {
        1: 'In ko je preteklo leto, ob času, ko hodijo kralji na boj, je peljal Joab ven vojne trume in opustošil deželo sinov Amonovih, in pride in oblega Rabo. David pa je ostal v Jeruzalemu. In Joab je udaril Rabo in jo razdejal.',
        2: 'In David vzame krono njih kralja z glave njegove, težko talent zlata in obloženo z dragimi kameni; in posadili so jo Davidu na glavo. Tudi plena iz mesta je odpeljal silno veliko.',
        3: 'In izpeljal je ljudstvo, ki je bilo v njem, in jih je postavil pri žagah in pri železnih mlatilnicah in pri sekirah. Tako je storil David vsem mestom sinov Amonovih. In David in vse ljudstvo se vrne v Jeruzalem.',
        4: 'Potem se vname vojska v Gezerju s Filistejci. Takrat je udaril Sibekaj Husajec Sipaja, iz sinov velikanovih; in bili so ponižani.',
        5: 'In zopet je bila vojna s Filistejci; in Elhanan, sin Jairov, je udaril Lahmija, brata Goliata Gatovca, ki je imel suličišče pri svoji sulici kakor tkalsko vratilo.',
        6: 'In zopet je bila bitka v Gatu, kjer je bil mož visoke postave, ki je imel po šest prstov na rokah in na nogah, skupaj štiriindvajset; tudi ta se je bil rodil velikanu.',
        7: 'Ko je ta sramotil Izraela, ga je ubil Jonatan, sin Simea, brata Davidovega.',
        8: 'Ti so se bili rodili velikanu v Gatu, in padli so po roki Davidovi in po roki služabnikov njegovih.',
    },
    21: {
        1: 'In Satan se je vzdignil zoper Izraela in izpodbodel Davida, da naj sešteje Izraela.',
        2: 'In David veli Joabu in poglavarjem ljudstva: Pojdite, seštejte Izraelce od Bersebe do Dana, in prinesite mi poročilo, da vem njih število!',
        3: 'In Joab reče: Gospod pridaj k ljudstvu svojemu stokrat toliko, kolikor jih je! Ali, gospod moj, kralj, niso li vsi gospoda mojega hlapci? Čemu zahteva to gospod moj? Zakaj se naj to šteje v pregreho Izraelu?',
        4: 'Vendar pa je obveljala beseda kraljeva zoper Joaba. Zatorej odide Joab in prehodi vse Izraelovo in se vrne v Jeruzalem.',
        5: 'In dal je Joab število preštetega ljudstva Davidu; in bilo je vsega Izraela tisočkrat tisoč in sto tisoč mož, ki so izdirali meč; iz Jude pa štiristo in sedemdeset tisoč mož, ki so izdirali meč.',
        6: 'A Levija in Benjamina ni štel ž njimi vred, kajti beseda kraljeva se je mrzila Joabu.',
        7: 'To povelje pa se je hudo videlo v očeh Božjih, in udaril je Izraela.',
        8: 'In David reče Bogu: Hudo sem grešil, da sem storil to; a sedaj, prosim, odpravi krivico hlapca svojega, kajti ravnal sem zelo nespametno!',
        9: 'In Gospod je govoril Gadu, Davidovemu vidcu, rekoč:',
        10: 'Pojdi in govóri Davidu in reci: Tako pravi Gospod: Troje ti ponujam, izberi si eno, da naj ti storim.',
        11: 'Pride torej Gad k Davidu in mu reče: Tako pravi Gospod: Izberi si:',
        12: 'bodisi tri leta lakote, ali da tri mesece bežiš pred nasprotniki svojimi, ko te dohiteva meč sovražnikov tvojih, ali pa tri dni meč Gospodov in kugo v deželi in angela Gospodovega, ki bo pogubljal po vseh mejah Izraelovih. Sedaj pa premisli, kakšen odgovor naj dam njemu, ki me je poslal.',
        13: 'In David reče Gadu: V stiski sem veliki! Rajši padem, prosim, v roko Gospodovo, kajti veliko je usmiljenje njegovo; le nikar naj ne padem v roko človeško!',
        14: 'Poslal je torej Gospod kugo nad Izraela, in pomrlo je iz Izraela sedemdeset tisoč mož.',
        15: 'In Bog pošlje angela proti Jeruzalemu, da ga pogubi; in ko je pogubljal, je pogledal Gospod in žal mu je bilo hudega; in veli angelu, ki je pokončeval: Dosti je, odtegni zdaj roko svojo! In angel Gospodov je stal pri gumnu Ornana Jebusejca.',
        16: 'David pa povzdigne oči in vidi angela Gospodovega stoječega med zemljo in nebom in v roki njegovi potegnjen meč, naperjen proti Jeruzalemu. Tedaj padejo David in starejšine, oblečeni v raševino, na obraze svoje.',
        17: 'In David reče Bogu: Nisem li jaz velel, naj se sešteje ljudstvo? Jaz sem tisti, ki sem grešil in zelo krivično ravnal, te ovce pa, kaj so storili? Roka tvoja, prosim, o Gospod, Bog moj, bodi zoper mene in zoper očeta mojega hišo, nikar zoper tvoje ljudstvo, da ga tepe!',
        18: 'Tedaj zapove angel Gospodov Gadu, da veli Davidu, naj gre gori in zgradi oltar Gospodu na gumnu Ornana Jebusejca.',
        19: 'In David je šel gori po besedi Gadovi, ki jo je govoril v imenu Gospodovem.',
        20: 'Ornan pa se ozre in zagleda angela, in štirje sinovi njegovi, ki so bili pri njem, se skrijejo; Ornan je namreč mlatil pšenico.',
        21: 'In ko David pride do Ornana, se ta ozre in zagleda Davida in gre z gumna ter se Davidu prikloni z obrazom do tal.',
        22: 'Tedaj reče David Ornanu: Prepústi mi kraj tega gumna, da na njem zgradim oltar Gospodu, prepústi mi ga za polno ceno, da bi nehala kuga med ljudstvom.',
        23: 'Ornan pa reče Davidu: Vzemi si ga, in stori naj ž njim gospod moj, kralj, kar se mu dobro vidi; glej, dam ti voli v žgalno daritev in mlatilnice za drva in pšenico v jedilno daritev: vse dam rad.',
        24: 'A kralj David reče Ornanu: Nikar, ampak res hočem to kupiti od tebe za polno ceno, ker ne vzamem, kar je tvojega, za Gospoda, in ne bom daroval žgalne daritve brez stroškov.',
        25: 'Dal je torej David Ornanu za tisti kraj šeststo zlatih seklov po teži.',
        26: 'In David je zgradil ondi oltar Gospodu in je daroval žgalne in mirovne daritve in klical Gospoda; on pa mu je odgovoril iz nebes po ognju na oltarju žgalnih daritev.',
        27: 'In Gospod ukaže angelu, in angel vtakne meč zopet v nožnico svojo.',
        28: 'V tistem času, ko je David videl, da mu je Gospod odgovoril na gumnu Ornana Jebusejca, je daroval ondi.',
        29: 'Kajti šator Gospodov, ki ga je naredil Mojzes v puščavi, in oltar žgalnih daritev, sta bila tisti čas na višavi v Gibeonu.',
        30: 'A David ni mogel predenj tja hoditi, da bi iskal Boga, tako je bil prestrašen zaradi meča angela Gospodovega.',
    },
    22: {
        1: 'In David reče: Tu bodi hiša Gospoda, Boga, in tu bodi oltar za žgalne daritve Izraelu!',
        2: 'In David ukaže, naj zbero tujce, ki so bili v deželi Izraelovi; in nastavi kamenarje, da sekajo kamene na štiri ogle za zgradbo hiše Božje.',
        3: 'In David je pripravil obilico železa za žeblje k durnicam pri vratih in za spojke, brona tudi toliko, da ga ni bilo moči stehtati,',
        4: 'tudi cedrovega lesa brez števila; kajti Sidonci in Tirci so pripeljali mnogo cedrovine Davidu.',
        5: 'In David je rekel: Salomon, sin moj, je mlad in šibek, hiša pa, ki se ima zidati za Gospoda, mora biti silno velika, da gre njen glas in njena slava po vseh deželah: pripravim torej zanjo. Oskrbel je torej David mnogo gradiva pred smrtjo svojo.',
        6: 'In pokliče sina svojega Salomona in mu zapove zgraditi hišo Gospodu, Bogu Izraelovemu.',
        7: 'In veli David Salomonu: Sin moj, jaz sem se namenil v srcu svojem, da zgradim hišo imenu Gospoda, Boga svojega.',
        8: 'Ali beseda Gospodova je prišla k meni, govoreč: Prelil si mnogo krvi in imel velike boje; ti ne boš zidal hiše imenu mojemu, ker si prelil mnogo krvi na zemljo vpričo mene.',
        9: 'Glej, sin se ti bo rodil, ki bode mož pokoja, in pripravim mu pokoj pred vsemi sovražniki njegovimi okoli; kajti Salomon mu bode ime, ker mir in pokoj dam Izraelu v dnevih njegovih.',
        10: 'On zgradi hišo imenu mojemu; in on mi bode sin, in jaz mu bodem oče, in kraljestva njegovega prestol utrdim nad Izraelom za vekomaj!',
        11: 'Sedaj pa bodi Gospod s teboj, sin moj, da ti gre po sreči in postaviš hišo Gospodu, Bogu svojemu, kakor je govoril zate.',
        12: 'Gospod ti samo daj razum in previdnost in ti poveri vlado nad Izraelom, da bi izpolnjeval zakon Gospoda, Boga svojega.',
        13: 'Tedaj boš imel srečo, ako boš pazil, da izpolnjuješ postave in sodbe, ki jih je Gospod ukazal Mojzesu za Izraela. Bodi močan in srčen, ne boj se in ne plaši se!',
        14: 'In glej, v trudovitem življenju svojem sem pripravil za hišo Gospodovo sto tisoč talentov zlata in tisočkrat tisoč talentov srebra, brona in železa pa, da ga ni moči stehtati, kajti preobilo ga je; lesa in kamenja sem tudi pripravil, ti pa lahko še prideneš k temu!',
        15: 'Vrhutega imaš pri sebi dosti delavcev, kamenosekov, klesarjev in obdelovalcev lesa in vsakršnih veščakov za vsakovrstna dela.',
        16: 'Zlatu, srebru, bronu, železu ni števila. Vstani in delaj, in Gospod bodi s teboj!',
        17: 'David je tudi zapovedal vsem knezom Izraelovim, naj pomagajo Salomonu, sinu njegovemu:',
        18: 'Ni li z vami Gospod, Bog vaš? in ni li vam oskrbel pokoja na vseh straneh? Kajti prebivalce te dežele je dal v mojo roko, in dežela je podvržena Gospodu in ljudstvu njegovemu.',
        19: 'Dajte torej srca svoja in duše svoje, da iščete Gospoda, Boga svojega! In vstanite in zidajte svetišče Gospoda Boga, da prineso skrinjo zaveze Gospodove in svete posode Božje v hišo, ki se ima zgraditi imenu Gospodovemu!',
    },
    23: {
        1: 'David je torej, ko je bil star in dni svojih sit, postavil Salomona, sina svojega, za kralja nad Izraelom.',
        2: 'In zbral je vse kneze Izraelove in duhovnike in levite.',
        3: 'Leviti pa so bili prešteti, od tridesetletnih in više, in njih število, od glave do glave, je bilo osemintrideset tisoč mož.',
        4: 'Iz teh je bilo štiriindvajset tisoč, ki naj bi nadzorovali delo pri hiši Gospodovi, in šest tisoč je bilo oblastnikov in sodnikov,',
        5: 'in štiri tisoč vratarjev in štiri tisoč, ki naj hvalijo Gospoda z godali, ki sem jih napravil, je rekel David, da se ž njimi poje hvala.',
        6: 'In David jih je razdelil v oddelke po sinovih Levijevih, po Gersonu, Kahatu in Merariju.',
        7: 'Gersonovci: Ladan in Simej.',
        8: 'Sinovi Ladanovi: Jehiel poglavar, Zetam in Joel, trije.',
        9: 'Sinovi Simejevi: Selomit, Haziel in Haran, trije. Ti so bili glave očetovinam Ladanovim.',
        10: 'Sinovi Simejevi pa: Jahat, Ziza, Jeuš in Berija. Ti štirje so bili sinovi Simejevi.',
        11: 'In Jahat je bil prvak in Ziza je bil drugi; a Jeuš in Berija nista imela mnogo sinov, zato so jih šteli za eno očetovsko hišo. –',
        12: 'Sinovi Kahatovi: Amram, Izhar, Hebron in Uziel, štirje.',
        13: 'Sinova Amramova: Aron in Mojzes. Aron pa je bil izločen, da bodi posvečen za najsvetejše, on in sinovi njegovi vekomaj, da naj palijo kadilo pred Gospodom, mu služijo in blagoslavljajo v njegovem imenu na vekomaj.',
        14: 'Kar se tiče Mojzesa, moža Božjega – sinovi njegovi so bili imenovani med rodom Levijevim.',
        15: 'Sinova Mojzesova: Gersom in Eliezer.',
        16: 'Sin Gersomov: Sebuel, poglavar.',
        17: 'In sin Eliezerjev: Rehabija, poglavar. In Eliezer ni imel več sinov, ali sinov Rehabijevih je bilo mnogo.',
        18: 'Sin Izharjev: Selomit, poglavar.',
        19: 'Sinovi Hebronovi: Jerija poglavar, Amarija, drugi, Jahaziel, tretji, in Jekameam, četrti.',
        20: 'Sinova Uzielova: Miha, poglavar, in Išija, drugi.',
        21: 'Sinova Merarijeva: Mahli in Musi. Sinova Mahlijeva: Eleazar in Kis.',
        22: 'In Eleazar je umrl, imel ni sinov, samo hčere; in njih bratranci, sinovi Kisovi, so jih vzeli za žene.',
        23: 'Sinovi Musijevi: Mahli, Eder in Jeremot, trije.',
        24: 'Ti so bili sinovi Levijevi po svojih očetovskih hišah, glave očetovinam, kakor so bili sešteti po imenih, od glave do glave, od dvajsetega leta in više, ki so opravljali delo službe pri hiši Gospodovi.',
        25: 'Kajti David je rekel: Gospod, Bog Izraelov, je pripravil pokoj ljudstvu svojemu, in on prebiva v Jeruzalemu na vekomaj;',
        26: 'zato tudi ni treba levitom nositi več šatora in vseh njegovih priprav za službo v njem.',
        27: 'Kajti po zadnjih besedah Davidovih so bili sinovi Levijevi prešteti od dvajsetletnih in više.',
        28: 'Zakaj njih stojišče je bilo ob strani sinovom Aronovim pri službi doma Gospodovega, da nadzirajo dvorišča in hrame in očiščevanje vseh svetih reči in opravljajo službo hiše Božje,',
        29: 'in naj skrbe za razporedbo kruhov in za belo moko k jedilni daritvi, bodisi od nekvašenih mlincev ali pa kar se peče v ponvi ali kar se praži, in za vsakršno težo in mero,',
        30: 'ter naj stojé vsako jutro, da hvalijo in slave Gospoda, takisto zvečer,',
        31: 'in darujejo vse žgalne daritve Gospodu ob sobotah, ob mlajih in ob določenih praznikih po predpisanem številu neprenehoma pred Gospodom,',
        32: 'in naj strežejo v straži pri shodnem šatoru in v straži svetišča in v straži pri sinovih Aronovih, bratih svojih, v službi hiše Gospodove.',
    },
    24: {
        1: 'Ti pa so oddelki sinov Aronovih: Sinovi Aronovi so bili: Nadab in Abihu, Eleazar in Itamar.',
        2: 'Nadab in Abihu pa sta umrla pred obličjem očeta svojega in nista imela otrok; zato sta bila Eleazar in Itamar duhovnika.',
        3: 'In razdelili so jih David in Zadok, iz sinov Eleazarjevih, in Ahimeleh, iz sinov Itamarjevih, po vrstah njih službe.',
        4: 'In med sinovi Eleazarjevimi se je našlo več moških glav nego med sinovi Itamarjevimi; in so jih takole razdelili: od sinov Eleazarjevih jih je bilo šestnajst poglavarjev očetovskih hiš in od sinov Itamarjevih osem poglavarjev očetovskih hiš.',
        5: 'Tako so bili razdeljeni po žrebu, ti kakor oni, kajti bili so knezi svetišča in knezi Božji od sinov Eleazarjevih in od sinov Itamarjevih.',
        6: 'In pisar Semaja, sin Netanelov, izmed levitov, jih je zapisal vpričo kralja in knezov in Zadoka duhovnika in Ahimeleha, sinu Abiatarjevega, in poglavarjev duhovniških in levitskih hiš: po eno očetovsko hišo se je jemalo za Eleazarja in po eno za Itamarja.',
        7: 'Prvi žreb pa je zadel Jehojariba, drugi Jedaja,',
        8: 'tretji Harima, četrti Seorima,',
        9: 'peti Malkija, šesti Mijamina,',
        10: 'sedmi Hakoza, osmi Abija,',
        11: 'deveti Jesua, deseti Sekanija,',
        12: 'enajsti Eliasiba, dvanajsti Jakima,',
        13: 'trinajsti Hupa, štirinajsti Jesebeaba,',
        14: 'petnajsti Bilga, šestnajsti Imerja,',
        15: 'sedemnajsti Hezirja, osemnajsti Hapizeza,',
        16: 'devetnajsti Petahija, dvajseti Jehezkela,',
        17: 'enaindvajseti Jakina, dvaindvajseti Gamula,',
        18: 'triindvajseti Delaja, štiriindvajseti Maazija.',
        19: 'To so bile njih vrste za službo, v katerih jim je bilo hoditi v hišo Gospodovo po naredbi njih očeta Arona, kakor mu je bil zapovedal Gospod, Bog Izraelov.',
        20: 'Od drugih sinov Levijevih pa: od sinov Amramovih: Subael; od sinov Subaelovih: Jehdeja.',
        21: 'Od Rehabija, iz sinov Rehabijevih: Išija, poglavar.',
        22: 'Od Izharjevcev: Selomot, iz sinov Selomotovih: Jahat.',
        23: 'In sinovi Hebronovi: Jerija, prvak, Amarija, drugi, Jahaziel tretji, Jekameam četrti.',
        24: 'Sinovi Uzielovi: Miha, iz sinov Mihovih: Samir.',
        25: 'Brat Mihov: Išija, iz sinov Išijevih: Zeharija.',
        26: 'Sinovi Merarijevi: Mahli in Musi; sinovi Jaazija, sinu njegovega.',
        27: 'Sinovi Merarijevi od Jaazija, sinu njegovega: Soham, Zakur in Ibri.',
        28: 'Od Mahlija: Eleazar, ki ni imel sinov.',
        29: 'Od Kisa, sinovi Kisovi: Jerahmeel.',
        30: 'In sinovi Musijevi: Mahli, Eder in Jerimot. Ti so bili sinovi levitov po svojih očetovskih hišah.',
        31: 'Tudi ti so žrebali kakor njih bratje, sinovi Aronovi, vpričo Davida kralja in Zadoka in Ahimeleka in poglavarjev duhovniških in levitskih hiš, in sicer enako glava očetovske hiše kakor njega najmanjši brat.',
    },
    25: {
        1: 'In David in poveljniki vojske so odločili za službo od sinov Asafovih, Hemanovih in Jedutunovih tiste, ki so imeli prorokovati s harfami, s psalmovimi citrami in s cimbali. In število mož, ki so opravljali to službo, je bilo:',
        2: 'od sinov Asafovih: Zakur, Jožef, Netanija in Asarela, sinovi Asafovi, pod vodstvom Asafa, ki je prorokoval po naredbi kraljevi.',
        3: 'Od Jedutuna, sinovi Jedutunovi: Gedalija, Zeri, Jesaija, Hasabija, Matitija in Simej, šest, pod vodstvom očeta svojega Jedutuna s harfo, ki je prorokoval, pojoč zahvalo in slaveč Gospoda.',
        4: 'Od Hemana, sinovi Hemanovi: Bukija, Matanija, Uziel, Sebuel, Jerimot, Hananija, Hanani, Eliata, Gidalti, Romamtiezer, Josbekasa, Maloti, Hotir, Mahaziot;',
        5: 'vsi ti so bili sinovi Hemana, kraljevega vidca v besedah Božjih; da bi povišal njegov rog, je dal Bog Hemanu štirinajst sinov in tri hčere.',
        6: 'Vsi ti so bili pod vodstvom očetov svojih pevci v hiši Gospodovi s cimbali, psalmovimi citrami in harfami, za službo doma Gospodovega. Asaf, Jedutun in Heman pa so bili odgovorni kralju.',
        7: 'In njih število ž njih brati vred, ki so bili poučeni v petju Gospodu, vseh izvežbanih je bilo dvesto oseminosemdeset.',
        8: 'In žrebali so zavoljo svoje službe, vsi enako, mali in veliki, učitelj in učenec.',
        9: 'Prvi žreb pa je zadel Asafa in je veljal Jožefu. Drugi Gedaliju, njemu in bratom in sinovom njegovim, dvanajsterim.',
        10: 'Tretji Zakurju, sinovom bratom njegovim, dvanajsterim.',
        11: 'Četrti Izriju, njegovim sinovom in bratom, dvanajsterim.',
        12: 'Peti Netaniju, njegovim sinom in bratom, dvanajsterim.',
        13: 'Šesti Bukiju, njegovim sinom in bratom, dvanajsterim.',
        14: 'Sedmi Jesarelu, njegovim sinom in bratom, dvanajsterim.',
        15: 'Osmi Jesaiju, njegovim sinom in bratom, dvanajsterim.',
        16: 'Deveti Mataniju, njegovim sinom in bratom, dvanajsterim.',
        17: 'Deseti Simeju, njegovim sinom in bratom, dvanajsterim.',
        18: 'Enajsti Azarelu, njegovim sinovom in bratom, dvanajsterim.',
        19: 'Dvanajsti Hasabiju, njegovim sinovom in bratom, dvanajsterim.',
        20: 'Trinajsti Subaelu, njegovim sinom in bratom, dvanajsterim.',
        21: 'Štirinajsti Matitiju, njegovim sinovom in bratom, dvanajsterim.',
        22: 'Petnajsti Jeremotu, njegovim sinom in bratom, dvanajsterim.',
        23: 'Šestnajsti Hananiju, njegovim sinovom in bratom, dvanajsterim.',
        24: 'Sedemnajsti Josbekasu, njegovim sinom in bratom, dvanajsterim.',
        25: 'Osemnajsti Hananu, njegovim sinovom in bratom, dvanajsterim.',
        26: 'Devetnajsti Malotiju, njegovim sinovom in bratom, dvanajsterim.',
        27: 'Dvajseti Eliatu, njegovim sinovom in bratom, dvanajsterim.',
        28: 'Edenindvajseti Hotirju, njegovim sinovom in bratom, dvanajsterim.',
        29: 'Dvaindvajseti Gidaltu, njegovim sinovom in bratom, dvanajsterim.',
        30: 'Triindvajseti Mahaziotu, njegovim sinovom in bratom, dvanajsterim.',
        31: 'Štirindvajseti Romamtiezerju, njegovim sinovom in bratom, dvanajsterim.',
    },
    26: {
        1: 'Oddelki vratarjev pa so bili: iz Korahovcev: Meselemija, sin Korejev, iz sinov Asafovih.',
        2: 'In Meselemija je imel sinove: Zeharija, prvenec, Jediael, drugi, Zebadija, tretji, Jatniel, četrti,',
        3: 'Elam, peti, Johanan, šesti, Eljehoenaj, sedmi.',
        4: 'In Obededom je imel sinove: Semaja, prvenec, Jozabad, drugi, Joah, tretji, Sakar, četrti, Netanel, peti,',
        5: 'Amiel, šesti, Isahar, sedmi, Peuletaj, osmi; kajti Bog ga je blagoslovil.',
        6: 'Tudi Semaju, sinu njegovemu, se je rodilo sinov, ki so vladali hiši očeta svojega; kajti bili so vrli junaki.',
        7: 'Sinovi Semajevi: Otni, Refael, Obed, Elzabad, čigar bratje so bili vrli možje, Elihu in Semahija.',
        8: 'Vsi ti od sinov Obededomovih, so bili s svojimi brati in sinovi vred vrli možje, sposobni za službo, dvainšestdeset od Obededomovih.',
        9: 'In Meselemija je imel sinove in brate, vrle može, osemnajst.',
        10: 'Tudi Hosa, iz sinov Merarijevih, je imel sinove: Simri, prvak (kajti dasi ni bil prvenec, ga je oče njegov postavil za prvaka),',
        11: 'Hilkija, drugi, Tebalija, tretji, Zeharija, četrti; vseh sinov in bratov Hosovih je bilo trinajst.',
        12: 'Ti oddelki vratarjev, poglavarski možje, so imeli straže enako kakor njih bratje, da služijo v hiši Gospodovi.',
        13: 'In žrebali so, enako mali kakor veliki, po očetovskih svojih hišah, za vsaka vrata.',
        14: 'In žreb za vrata proti vzhodu je bil Selemiju. Potem so vrgli kocko za Zeharija, sina njegovega, razumnega svetovalca, in njega je zadel žreb za vrata proti severu.',
        15: 'Obededomu vrata proti jugu, sinom njegovim pa skladišče.',
        16: 'A Supimu in Hosu proti zahodu ob vratih Saleheta, na cesti, ki se vije kvišku, straža proti straži.',
        17: 'Proti vzhodu je bilo šest levitov; proti polnoči na dan štiri, proti poldnevu na dan štiri in pri skladišču po dva in dva.',
        18: 'Pri Parbarju pa, proti zahodu, štirje na cesti in dva ob Parbarju.',
        19: 'To so bili oddelki vratarjev, iz sinov Korahovcev in iz sinov Merarijevih.',
        20: 'Iz levitov pa je bil Ahija nad zakladi hiše Božje in nad zakladi posvečenih reči.',
        21: 'Sinovi Ladanovi, sinovi Gersonovcev od Ladana, poglavarji očetovskih hiš od Ladana Gersonovca, so bili Jehielci.',
        22: 'Sinova Jehielova, Zetam in Joel, brat njegov, sta bila nad zakladi hiše Gospodove.',
        23: 'Iz Amramovcev, iz Izharjevcev, iz Hebroncev, iz Uzielcev...',
        24: 'in Sebuel, sin Gersoma, sinu Mojzesovega, je bil poglavar nad zakladi.',
        25: 'In bratje njegovi, od Eliezerja: tega sin Rehabija, tega sin Jesaija, tega sin Joram, tega sin Zihri, tega sin Selomot.',
        26: 'Ta Selomot in bratje njegovi so bili nad zakladi posvečenih reči, ki so jih bili posvetili David kralj in poglavarji očetovin, poveljniki čez tisoč in čez sto in poveljniki vojske.',
        27: 'Od plena, ki so ga pridobili v vojni, so posvetili v podporo hiši Gospodovi.',
        28: 'In vse, kar je posvetil Samuel videc in Savel, sin Kisov, in Abner, sin Nerov, in Joab, sin Zervijin, kdorkoli je kaj posvetil, je bilo pod roko Selomota in bratov njegovih.',
        29: 'Iz Izharjevcev, Kenanija in sinovi njegovi so bili za zunanja opravila nad Izraelom, za oblastnike in sodnike.',
        30: 'Iz Hebroncev, Hasabija in bratje njegovi, sedemnajststo vrlih mož, so nadzorovali Izraela tostran Jordana, proti zahodu, za vsakršna opravila Gospodova in za službo kraljevo.',
        31: 'Iz Hebroncev je bil Jerija, poglavar Hebroncem po njih rodovih, po njih očetovinah. V štiridesetem letu vladanja Davidovega so jih iskali, in našli so med njimi vrle junake v Jazerju v Gileadu.',
        32: 'In bratov njegovih, vrlih mož, je bilo dva tisoč sedemsto, poglavarjev očetovin, ki jih je David postavil v nadzorstvo Rubenovcev, Gadovcev in polovice Manasejevega rodu, za vse Božje reči in za zadeve kraljeve.',
    },
    27: {
        1: 'In to so sinovi Izraelovi po njih številu, poglavarji očetovin in poveljniki čez tisoč in čez sto in njih oblastniki, ki so služili kralju po redu oddelkov, kakor so prihajali in odhajali mesec za mesecem, vse mesece v letu; vsak oddelek je štel štiriindvajset tisoč.',
        2: 'Nad prvim oddelkom v prvem mesecu je bil Jasobeam, sin Zabdielov, in v njegovem oddelku jih je bilo štiriindvajset tisoč.',
        3: 'On je bil iz sinov Perezovih prvak vseh poveljnikov vojske za prvi mesec.',
        4: 'In nad oddelkom drugega meseca je bil Dodaj Ahohovec in v oddelku njegovem je bil knez Miklot, in v oddelku njegovem jih je bilo štiriindvajset tisoč.',
        5: 'Tretji poveljnik vojske v tretjem mesecu je bil Benaja, sin Jojada duhovnika, glavar, in v oddelku njegovem jih je bilo štiriindvajset tisoč.',
        6: 'To je tisti Benaja, ki je bil eden izmed tridesetih junakov in nad tridesetimi; in nad oddelkom njegovim je bil Amizabad, sin njegov.',
        7: 'Četrti poveljnik v četrtem mesecu je bil Asahel, brat Joabov, in za njim Zebadija, sin njegov, in v oddelku njegovem jih je bilo štiriiindvajset tisoč.',
        8: 'Peti poveljnik v petem mesecu je bil Samhut Izrahovec, in v oddelku njegovem jih je bilo štiriindvajset tisoč.',
        9: 'Šesti v šestem mesecu je bil Ira, sin Ikeša Tekojčana, in v oddelku njegovem jih je bilo štiriindvajset tisoč.',
        10: 'Sedmi v sedmem mesecu je bil Helez Pelonjan iz sinov Efraimovih, in v oddelku njegovem jih je bilo štiriindvajset tisoč.',
        11: 'Osmi v osmem mesecu je bil Sibekaj Husajec iz Zerahovcev, in v oddelku njegovem jih je bilo štiriindvajset tisoč.',
        12: 'Deveti v devetem mesecu je bil Abiezer Anatotčan iz Benjamincev, in v oddelku njegovem jih je bilo štiriindvajset tisoč.',
        13: 'Deseti v desetem mesecu je bil Maharaj Netofatčan iz Zerahovcev, in v oddelku njegovem jih je bilo štiriindvajset tisoč.',
        14: 'Enajsti v enajstem mesecu je bil Benaja Piratončan iz sinov Efraimovih, in v oddelku njegovem jih je bilo štiriindvajset tisoč.',
        15: 'Dvanajsti v dvanajstem mesecu je bil Heldaj Netofatčan, od Otniela, in v oddelku njegovem jih je bilo štiriindvajset tisoč.',
        16: 'Dalje nad rodovi Izraelovimi: Rubenovcem je bil vojvoda Eliezer, sin Zihrijev; Simeoncem Sefatija, sin Maake;',
        17: 'Levitskim Hasabija, sin Kemuelov, Aronovim pa Zadok;',
        18: 'Judovcem Elihu, eden iz bratov Davidovih; Isaharjevcem Omri, sin Mihaelov;',
        19: 'Zebulonovcem Ismaja, sin Obadija; Neftalijevim Jeremot, sin Azrielov;',
        20: 'sinom Efraimovim Hosea, sin Azazijev; polovici rodu Manasejevega Joel, sin Pedajev;',
        21: 'polovici rodu Manasejevega v Gileadu Ido, sin Zeharijev; Benjamincem Jaasiel, sin Abnerjev;',
        22: 'Danovim Azarel, sin Jerohamov. Ti so bili poveljniki rodovom Izraelovim.',
        23: 'David pa ni poizvedoval števila tistih, ki jim je bilo manj nego dvajset let, zakaj Gospod je bil rekel, da razmnoži Izraela enako zvezdam nebeškim.',
        24: 'Joab, sin Zervijin, je začel šteti, a dokončal ni; in prišla je jeza Božja zaradi tega nad Izraela. Zato ni bilo to število vpisano v letopise kralja Davida.',
        25: 'In nad kraljevimi zakladi je bil Azmavet, sin Adielov; in nad zakladi po deželi, v mestih in po vaseh in gradovih je bil Jonatan, sin Uzijev.',
        26: 'In nad delavci na polju, ki so obdelovali zemljo, je bil Ezri, sin Helubov.',
        27: 'In nad vinogradi je bil Simej Ramatejec; nad pridelki vinogradov, nad zalogami v vinskih hramih je pa bil Zabdi Sifmijan.',
        28: 'Nad oljkovim in smokovim drevjem, ki je bilo v nižini, je bil Baalhanan Gederski; in nad shrambami olja Joas.',
        29: 'In nad govedi, ki so se pasla v Saronu, je bil Sitraj Saronski, nad govedi v dolinah pa Safat, sin Adlajev.',
        30: 'In nad velblodi Obil Izmaelec, nad oslicami pa Jehdeja Meronotičan,',
        31: 'nad drobnico pa Jaziz Hagarenec. Vsi ti so bili oskrbniki imetja kralja Davida.',
        32: 'A Jonatan, stric Davidov, je bil svetovalec, razumen mož in pismouk. In Jehiel, sin Hakmonijev, je bil pri kraljevih sinovih.',
        33: 'Ahitofel pa je bil kraljev svetovalec, a Husaj Arkičan kraljev prijatelj.',
        34: 'Za Ahitofelom je bil Jojada, sin Benaja, in Abiatar. In poveljnik kraljevi vojski je bil Joab.',
    },
    28: {
        1: 'In David zbere v Jeruzalem vse poglavarje Izraelove, vojvode rodov in poveljnike trum, ki so stregli kralju zaporedoma, in poveljnike čez tisoč in čez sto in oskrbnike imetja in posestev kraljevih in sinov njegovih, z dvorniki in junaki in z vsemi hrabrimi možmi vred.',
        2: 'Tedaj se postavi kralj David na noge in govori: Poslušajte me, bratje moji in ljudstvo moje! Jaz sem se namenil v srcu svojem, da zgradim hišo počivanja skrinji zaveze Gospodove in podnožju nog Boga našega, in sem se pripravljal za zidanje.',
        3: 'Ali Bog mi je rekel: Ti ne boš gradil hiše mojemu imenu, ker si mož vojščak in si kri prelival.',
        4: 'Toda mene je Gospod, Bog Izraelov, izvolil iz vse hiše očeta mojega, da bodem kralj Izraelu vekomaj; zakaj Judo si je izbral, da bodi vojvoda, in v družini Judovi hišo očeta mojega, in med sinovi očeta mojega si je blagovoljno izbral mene, da me postavi za kralja vsemu Izraelu;',
        5: 'a med vsemi sinovi mojimi – kajti mnogo sinov mi je dal Gospod – si je izvolil Salomona, sina mojega, da bo sedel na prestolu kraljestva Gospodovega nad Izraelom.',
        6: 'In mi je dejal: Salomon, sin tvoj, bo zgradil hišo mojo in veže moje, zakaj izvolil sem ga, da mi bodi sin in jaz mu bodem oče.',
        7: 'In utrdim kraljestvo njegovo na vekomaj, ako bode stanovitno izpolnjeval zapovedi in sodbe moje, kakor se danes godi.',
        8: 'Sedaj torej, vpričo vsega Izraela, zbora Gospodovega, in vpričo Boga našega velim: Izpolnjujte in v čislih imejte vse zapovedi Gospoda, Boga svojega, da bi dedno vladali to dobro deželo in jo v dedno last zapustili otrokom svojim za seboj na vekomaj.',
        9: 'Ti pa Salomon, sin moj, spoznaj Boga, ki je Bog očeta tvojega, in mu služi z nerazdeljenim srcem in z radovoljnim duhom! Kajti Gospod preiskuje vsa srca in razume vse naklepe misli. Ga li boš iskal, ga najdeš; ako ga pa zapustiš, te zavrže vekomaj!',
        10: 'Sedaj torej pazi, kajti Gospod te je izvolil, da zgradiš hišo za svetišče; močan bodi in delaj!',
        11: 'Nato je dal David Salomonu, sinu svojemu, načrt veže pri templju in njegovih hiš in zakladnic in zgornjih sob in notranjih hramov in prostora za spravni pokrov,',
        12: 'in načrt vsega, kar mu je bilo v duhu: o dvorih hiše Gospodove in o vseh hramih naokoli, o zakladnicah hiše Božje in zakladnicah posvečenih reči;',
        13: 'tudi o oddelkih duhovnikov in levitov in o vsem delu službe v hiši Gospodovi in o vseh pripravah za službo v hiši Gospodovi;',
        14: 'o zlatu po teži za vsakovrstne zlate posode v službo, o teži srebra za vse srebrne posode, za vsakovrstno posodje v službo,',
        15: 'in je določil težo zlata za zlate svečnike in njih svetilnice po teži za vsak svečnik in njegove svetilnice, in za svečnike srebrne po teži, kolikor treba za vsak svečnik in njegove svetilnice;',
        16: 'tudi težo zlata za mize z razvrščenimi kruhi, za vsako mizo, in srebra za srebrne mize;',
        17: 'tudi čistega zlata za vilice in čaše in konvice, in za zlate kupe, za vsako kupo po njeni teži, in za srebrne kupe, za vsako po njeni teži,',
        18: 'in za kadilni oltar prečiščenega zlata po teži, in za podobo voza kerubov, ki razprostirata peruti in pokrivata skrinjo zaveze Gospodove.',
        19: 'O vsem tem, je rekel David, o vseh posameznostih načrta me je poučil Gospod v pismu, ko je bila roka njegova nad menoj.',
        20: 'In David je dejal Salomonu, sinu svojemu: Bodi močan in srčen, in delaj! ne boj se in ne plaši se, zakaj Gospod Bog, moj Bog, je s teboj, ne odtegne se ti in te ne zapusti, dokler ne dokončaš vsega dela za službo hiše Gospodove.',
        21: 'In glej, so tu oddelki duhovnikov in levitov za vso službo hiše Božje, in bodo pri tebi prostovoljniki za vsako delo, izurjeni v vsakovrstnem delu, tudi poveljniki in vse ljudstvo ti. bo povsem na razpolago.',
    },
    29: {
        1: 'In kralj David reče vsemu zboru: Salomon, sin moj, ki je njega samega izvolil Bog, je še mlad in šibek, in delo je veliko, kajti tista palača ni za človeka, ampak za Gospoda Boga.',
        2: 'Jaz pa sem z vsemi močmi svojimi pripravil za hišo Boga svojega zlata za zlate, srebra za srebrne, brona za bronaste, železa za železne, lesa za lesene stvari; kamenov oniksovih in vdelanih, kamenov za olepšavo in raznobarvnih in vsakovrstnih dragih kamenov in belega marmornjaka v obilici.',
        3: 'Razen tega, ker me veseli hiša mojega Boga, sem dal iz lastnega zaklada zlata in srebra za hišo Boga svojega poleg vsega, kar sem oskrbel za sveto hišo:',
        4: 'tri tisoč talentov zlata, zlata iz Ofirja, in sedem tisoč talentov prečiščenega srebra, da se ž njim prevlečejo hišne stene,',
        5: 'zlata pa za zlate in srebra za srebrne stvari in za vsakovrstne naprave po rokah umetnikov. In kdo je radovoljen, danes napolniti roko svojo za Gospoda?',
        6: 'Tedaj so se izkazali radovoljne poglavarji očetovin in knezi rodov Izraelovih in poveljniki čez tisoč in čez sto in oskrbniki kraljevih opravil,',
        7: 'in so darovali za službo hiše Božje pet tisoč talentov zlata in deset tisoč dárikov, srebra pa deset tisoč talentov in brona osemnajst tisoč talentov in železa sto tisoč talentov.',
        8: 'In tisti, pri katerih so se našli dragi kameni, so jih dali v zaklad hiše Gospodove, pod roko Jehiela Gersonovca.',
        9: 'Tedaj se je ljudstvo veselilo, da so radovoljno darovali, ker z nerazdeljenim srcem so to poklonili Gospodu prostovoljno, tudi kralj David se je radoval z velikim veseljem.',
        10: 'In David je hvalil Gospoda vpričo vsega zbora in je dejal: Hvaljen bodi, o Gospod, Bog Izraela, očeta našega, od vekov na veke!',
        11: 'Tvoja, o Gospod, je velikost in moč in slava in dika in veličastvo; zakaj vse, kar je v nebesih in na zemlji, je tvoje. Tvoje je kraljestvo, o Gospod, in ti si povišan kot glava nad vsem!',
        12: 'Bogastvo in čast prihaja od tebe, in ti si vladar vsemu, in v roki tvoji je moč in oblast, in v tvoji roki je poveličati in ojačiti vse.',
        13: 'Sedaj torej, Bog naš, te zahvaljujemo in hvalimo ime slave tvoje.',
        14: 'Saj kdo sem jaz in kdo ljudstvo moje, da bi imeli moč, toliko radovoljno darovati tebi? Kajti od tebe je vse, in iz roke tvoje smo prejeli in dali tebi.',
        15: 'Zakaj mi smo tujci pred teboj in priseljenci, kakor so bili vsi očetje naši; dnevi naši na zemlji so kakor senca in ni upanja, da tu ostanemo.',
        16: 'O Gospod, Bog naš, vsa ta obilna množina, ki smo jo pripravili v zgradbo hiše tvoje, svetemu imenu tvojemu, je iz roke tvoje in vse to je tvoje.',
        17: 'Vem tudi, moj Bog, da preiskuješ srce in prijetna ti je preprostost. Jaz torej sem iz preprostosti srca svojega vse to radovoljno daroval, in sedaj sem z veseljem videl ljudstvo tvoje, ki je tu pričujoče, da je radovoljno darovalo tebi.',
        18: 'O Gospod, Bog Abrahama, Izaka in Izraela, očetov naših, ohrani vekomaj tako misel in namero v srcu tvojega ljudstva in obračaj njih srca k sebi!',
        19: 'In daj Salomonu, sinu mojemu, nerazdeljeno srce, da izpolnjuje zapovedi tvoje, pričevanja tvoja in postave tvoje in da stori vse in zgradi palačo, ki sem oskrbel zanjo priprave!',
        20: 'In David je rekel vsemu zboru: Hvalite sedaj Gospoda, Boga svojega! In ves zbor je hvalil Gospoda, očetov svojih Boga, in pripognili so se in storili poklon Gospodu in kralju.',
        21: 'In darovali so žrtve Gospodu, in drugo jutro potem so darovali Gospodu žgalne daritve: tisoč juncev, tisoč ovnov, tisoč jagnjet ž njih pitnimi daritvami vred, in obilo klalnih daritev za vsega Izraela,',
        22: 'in so jedli in pili pred Gospodom tisti dan z veliko radostjo. In so postavili Salomona, sina Davidovega, v drugič za kralja in ga pomazilili Gospodu za vojvodo in Zadoka za duhovnika.',
        23: 'In Salomon je zasedel prestol Gospodov kot kralj namesto Davida, očeta svojega, in uspevalo mu je, in ves Izrael ga je poslušal.',
        24: 'In vsi poglavarji in junaki, tudi vsi sinovi kralja Davida so se podvrgli kralju Salomonu.',
        25: 'In Gospod je jako poveličal Salomona pred očmi vsega Izraela in mu je dodelil tako veličastno kraljevanje, kakršnega ni imel pred njim noben kralj v Izraelu.',
        26: 'Tako je bil David, sin Jesejev, kralj vsemu Izraelu.',
        27: 'Časa pa, kar je kraljeval Izraelu, je bilo štirideset let: sedem let je vladal v Hebronu in triintrideset v Jeruzalemu.',
        28: 'In umrl je v lepi starosti, sit svojih dni, bogastva in časti. In Salomon, sin njegov, je kraljeval na mestu njegovem.',
        29: 'Dejanja Davidova pa, prva in poslednja, glej, zapisana so v zgodbah Samuela vidca in v zgodbah Natana proroka in v zgodbah Gada vidca',
        30: 'z vsem njegovim kraljevanjem in z močjo njegovo in s časi, ki so prešli pod njim čez Izraela in čez vsa kraljestva dežel.',
    },
}
